NAME = 'GerLeoNA28: Leonberger Bibel, NT (NA28)'
BOOK = 'Acts'

CHAPTERS = {
    1: {
        1: 'Den ersten Bericht habe ich über alles angefertigt, oh Theophilus, was Jesus zu tun und zu lehren begonnen hat,',
        2: 'bis zu dem Tag, an dem er hinaufgenommen wurde, nachdem er den Aposteln, die er ausgewählt hatte, durch den heiligen Geist Anweisungen erteilt hatte.',
        3: 'Ihnen erwies er sich selbst ja als Lebender (nachdem er gelitten hatte) mit vielen überzeugenden Beweisen, indem er ihnen über einen Zeitraum von vierzig Tagen sichtbar wurde und darüber sprach, ‹was das Reich Gottes betrifft›.',
        4: 'Und während er mit ihnen zusammen war, befahl er ihnen, sich von Jerusalem nicht zu entfernen, sondern die Verheißung des Vaters abzuwarten, „die ihr von mir gehört habt;',
        5: 'denn Johannes hat mit Wasser getauft, ihr aber werdet ‹in ein paar Tagen› mit dem heiligen Geist getauft werden.“',
        6: 'Diejenigen also, die versammelt waren, befragten ihn und sagten: „Herr, stellst du zu dieser Zeit das Königreich für Israel wieder her?“',
        7: 'Da sagte er zu ihnen: „Es ist nicht eure [Aufgabe], Zeitspannen oder Zeitpunkte zu kennen, die der Vater in seiner Vollmacht bestimmt hat,',
        8: 'ihr werdet jedoch Kraft bekommen, wenn der heilige Geist auf euch gekommen ist, und ihr werdet meine Zeugen sein, in Jerusalem und in ganz Judäa und Samaria und bis ans Ende der Erde.“',
        9: 'Und nachdem er das gesagt hatte, wurde er – während sie zusahen – emporgehoben, und eine Wolke nahm ihn von ihren Augen weg.',
        10: 'Und wie sie in den Himmel starrten, während er ging, siehe!, da standen zwei Männer in weißen Gewändern bei ihnen,',
        11: 'und die sagten: „Männer von Galiläa, was steht ihr herum und schaut in den Himmel? Dieser Jesus, der von euch in den Himmel hinaufgenommen wurde, wird auf dieselbe Weise kommen, wie ihr ihn habt in den Himmel gehen sehen.“',
        12: 'Daraufhin kehrten sie nach Jerusalem zurück vom sogenannten Ölberg, der nahe bei Jerusalem liegt, ‹eine Sabbatreise entfernt›.',
        13: 'Und als sie hinkamen, stiegen sie hinauf in das Oberzimmer, wo sie untergebracht waren: Petrus und Johannes und Jakobus und Andreas, Philippus und Thomas, Bartholomäus und Matthäus, Jakobus, [der Sohn] des Alphäus, und Simon der Zelot und Judas, [der Sohn] des Jakobus.',
        14: 'Diese alle hielten einmütig fest am Gebet, zusammen mit den Frauen und Maria, der Mutter von Jesus, und seinen Geschwistern.',
        15: 'Und in diesen Tagen stand Petrus im Kreis der Brüder auf und sagte (es war eine Menge von etwa hundertzwanzig Personen an demselben [Ort]):',
        16: '„Männer, Geschwister, es musste sich die Schrift erfüllen, die der heilige Geist durch den Mund Davids vorausgesagt hat über Judas, der ein Wegführer für die wurde, die Jesus verhaftet haben,',
        17: 'denn er wurde zu uns gezählt und hat das Los dieses Dienstes erlangt.',
        18: 'Dieser hat dann einen Acker vom Lohn der Ungerechtigkeit erworben, und weil er kopfüber gestürzt ist, platzte er mitten [entzwei], und alle seine Eingeweide haben sich ergossen;',
        19: 'und es ist allen Bewohnern Jerusalems bekannt geworden, sodass jener Acker in ihrem eigenen Dialekt ‚Akeldama‘genannt wird (das heißt: Blutacker).',
        20: 'Denn es steht geschrieben im Buch der Psalmen: ‚Seine Unterkunft soll wüst werden, / und kein Bewohner soll darin sein‘, und: ‚Seinen Platz soll ein anderer einnehmen.‘',
        21: 'Es muss also von den Männern, die während der ganzen Zeit mit uns mitgegangen sind, in der der Herr Jesus bei uns ein- und ausging,',
        22: 'angefangen von der Taufe des Johannes bis zu dem Tag, als er von uns hinaufgenommen wurde … einer von ihnen [muss] zusammen mit uns Zeuge seiner Auferstehung werden.“',
        23: 'Und sie stellten zwei [Kandidaten] auf: Josef, genannt Barsabbas, der [mit Beinamen] Justus gerufen wurde, und Matthias.',
        24: 'Und sie beteten und sagten: „Du, Herr, Kenner der Herzen aller [Menschen], zeige uns, wen du ausgewählt hast – einen von diesen beiden –,',
        25: 'um den Platz dieses Dienstes und Apostelamtes zu empfangen, von dem Judas abgetreten ist, um an seinen eigenen Platz zu gehen.“',
        26: 'Dann gaben sie ihnen Lose, und das Los fiel auf Matthias, und er wurde zu den elf Aposteln gezählt.',
    },
    2: {
        1: 'Und als sich der Tag des Pfingstfestes erfüllte, waren sie alle beisammen an demselben [Ort],',
        2: 'und plötzlich entstand aus dem Himmel ein Brausen wie von einem aufkommenden, stürmischen Wind, und es füllte das ganze Haus, wo sie saßen.',
        3: 'Und es erschienen ihnen Zungen wie aus Feuer, die sich zerteilten; und es setzte sich auf jeden Einzelnen von ihnen,',
        4: 'und sie alle wurden vom heiligen Geist erfüllt und begannen, in anderen Sprachen zu reden, wie der Geist es ihnen eingab auszusprechen.',
        5: 'Nun wohnten in Jerusalem Judäer, fromme Männer aus jedem Volk unter dem Himmel;',
        6: 'als nun dieses Geräusch entstand, kam die Schar zusammen und war verwirrt, weil ein jeder sie in seinem eigenen Dialekt reden hörten;',
        7: 'sie waren aber erstaunt und verwundert, sodass sie sagten: „Siehe!, sind nicht alle diese [Leute], die [hier] reden, Galiläer?',
        8: 'Und wieso hören wir sie ein jeder in unserem eigenen Dialekt, mit dem wir geboren wurden?',
        9: 'Parther und Meder und Elamiter, und die Bewohner von Mesopotamia, Judäa und auch Kappadokia, von Pontus und Asia,',
        10: 'von Phrygia und auch Pamphylia, Ägypten und den Teilen Libyens, die Richtung Kyrene [liegen], und die gastierenden Römer,',
        11: 'Judäer und auch Proselyten, Kreter und Araber – wir hören sie in den anderen Sprachen die großartigen [Dinge] Gottes reden.“',
        12: 'Sie alle waren aber erstaunt und ratlos, sodass einer zum anderen sagte: „Was soll das bedeuten?“',
        13: 'Andere wiederum spotteten und sagten: „Mit süßem Wein sind sie angefüllt.“',
        14: 'Und Petrus stellte sich zusammen mit den elf [Aposteln] hin und erhob seine Stimme, und er erklärte ihnen: „Männer von Judäa und all ihr Bewohner Jerusalems, Folgendes sei euch bekannt, und schenkt meinen Worten Gehör.',
        15: 'Denn diese [Leute] sind nicht betrunken, wie ihr vermutet, denn es ist [erst] die dritte Stunde des Tages,',
        16: 'sondern dies ist, was durch den Propheten Joël gesagt ist:',
        17: 'Und es wird in den letzten Tagen geschehen, spricht Gott, / da werde ich ausgießen von meinem Geist über die ganze Menschheit, / und eure Söhne und eure Töchter werden weissagen, / und eure jungen Leute werden Visionen sehen, / und eure Alten werden Träume träumen; /',
        18: 'und sogar über meine Knechte und über meine Mägde werde ich in jenen Tagen / von meinem Geist ausgießen, und sie werden weissagen. /',
        19: 'Und ich werde Wunder oben im Himmel geben / und Zeichen unten auf der Erde, / Blut und Feuer und Rauch. /',
        20: 'Die Sonne wird verwandelt werden zu einer Finsternis / und der Mond zu Blut, / bevor der große und denkwürdige Tag des Herrn kommt.',
        21: 'Und es wird [so] sein: jeder, der den Namen des Herrn anruft, gerettet werden wird.',
        22: 'Männer von Israel, hört diese Worte! Jesus den Nazoräer, einen Mann, der von Gott euch gegenüber durch Wunderkräfte und Wunder und Zeichen ausgewiesen worden ist, mit denen Gott durch ihn in unserer Mitte gehandelt hat, wie ihr selbst wisst …',
        23: 'diesen [Mann], ausgeliefert durch den festgelegten Plan und die Vorsehung Gottes, habt ihr durch die Hand der Gesetzlosen [ans Kreuz] genagelt und umgebracht.',
        24: 'Ihn hat Gott auferstehen lassen, nachdem er die Wehen des Todes aufgelöst hatte, weil er nicht von ihm festgehalten werden konnte.',
        25: 'Denn David sagt über ihn: ‚Ich sah den Herrn dauernd vor mir, weil er zu meiner Rechten ist, damit ich nicht wanke.',
        26: 'Deshalb freute sich mein Herz und jubelte meine Zunge, außerdem wird auch mein Fleisch auf Hoffnung ruhen.',
        27: 'Denn du wirst meine Seele nicht dem Hades überlassen, und du wirst nicht zulassen, dass dein Heiliger Verwesung sehe.',
        28: 'Du hast mir Wege des Lebens bekannt gemacht, du wirst mich mit deinem Angesicht mit Frohsinn erfüllen.‘',
        29: 'Männer, Brüder, es ist erlaubt, mit Freimütigkeit zu euch über den Stammvater David zu sprechen: und zwar starb er und wurde begraben, und sein Grab ist unter uns bis zu diesem Tag.',
        30: 'Da er also ein Prophet war und wusste, dass Gott ihm mit einem Eid geschworen hatte, ‹einen seiner Nachkommen› auf seinen Thron zu setzen,',
        31: 'redete er vorausschauend über die Auferstehung des Gesalbten, dass weder er dem Hades überlassen noch sein Fleisch Verwesung sehen würde.',
        32: 'Diesen Jesus hat Gott auferstehen lassen, wovon wir alle Zeugen sind.',
        33: 'Nachdem er also durch die rechte [Hand] Gottes erhöht worden ist und die Verheißung des heiligen Geistes vom Vater erhalten hat, goss er das aus, was ihr auch seht und hört.',
        34: 'David ist nämlich nicht in die Himmel hinaufgestiegen, er selbst sagt aber: ‚Es sprach der Herr zu meinem Herrn: Setze dich zu meiner Rechten, /',
        35: 'bis ich deine Feinde hinlege als Schemel für deine Füße.‘',
        36: 'Das ganze Haus Israel soll also eindeutig erkennen, dass Gott ihn sowohl zum Herrn als auch zum Gesalbten gemacht hat – diesen Jesus, den ihr gekreuzigt habt.“',
        37: 'Als sie nun das hörten, wurden sie im Herzen getroffen, und sie sagten zu Petrus und den übrigen Aposteln: „Was sollen wir tun, Männer, Brüder?“',
        38: 'Petrus aber sagt zu ihnen: „Tut Buße, und jeder von euch soll sich taufen lassen auf den Namen von Jesus Christus zur Vergebung eurer Sünden, dann werdet ihr das Geschenk des heiligen Geistes erhalten.',
        39: 'Die Verheißung gilt nämlich euch und euren Kindern und allen in der Ferne, so viele auch immer der Herr, unser Gott, hinzurufen wird.“',
        40: 'Und mit vielen weiteren Worten legte er Zeugnis ab, und er mahnte sie und sagte: „Lasst euch retten aus dieser verkehrten Generation!“',
        41: 'Diejenigen also, die sich seine Rede zu Herzen nahmen, ließen sich taufen. Und an jenem Tag wurden etwa 3.000 Personen hinzugefügt.',
        42: 'Und sie hielten fest an der Lehre der Apostel und an der Gemeinschaft, dem Brotbrechen und den Gebeten.',
        43: 'Es wurde aber jede Seele ehrfürchtig, und viele Wunder und Zeichen geschahen durch die Apostel.',
        44: 'Aber alle, die glaubten, waren an demselben [Ort], und sie hatten alles gemeinsam,',
        45: 'und die Besitztümer und die Güter verkauften sie, und sie verteilten sie an alle, je nachdem wie einer Not hatte;',
        46: 'und täglich verharrten sie einmütig im Tempel und brachen Brot von Haus zu Haus, sie nahmen zusammen Mahlzeiten ein mit einem fröhlichen und ungeteilten Herzen,',
        47: 'lobten Gott und hatten Gunst beim ganzen Volk. Der Herr aber fügte täglich diejenigen hinzu, die an demselben [Ort] gerettet wurden.',
    },
    3: {
        1: 'Petrus und Johannes aber stiegen hinauf zum Tempel zur Stunde des Gebets, die neunte [Stunde].',
        2: 'Und ein Mann, der ‹von Geburt an› gelähmt war, wurde herangetragen, den legten sie Tag für Tag an die Tür des Tempels, die „die Schöne“heißt, um Almosen von denen zu erbetteln, die in den Tempel hineingingen;',
        3: 'er sah, dass Petrus und Johannes vorhatten, in den Tempel hineinzugehen, und bat darum, ein Almosen zu erhalten.',
        4: 'Da richtete Petrus den Blick auf ihn, zusammen mit Johannes, und sagte: „Schau uns an!“',
        5: 'Er aber achtete auf sie und erwartete, etwas von ihnen zu erhalten.',
        6: 'Da sagte Petrus: „Silber und Gold besitze ich nicht, aber was ich habe, das gebe ich dir: Im Namen von Jesus Christus dem Nazoräer – steh auf und geh umher!“',
        7: 'Und er ergriff ihn bei der rechten Hand und richtete ihn auf; und augenblicklich wurden seine Füße und Knöchel gestärkt.',
        8: 'Und er sprang auf und stand hin und ging umher, und er ging zusammen mit ihnen in den Tempel hinein, ging umher und sprang und lobte Gott.',
        9: 'Und das ganze Volk sah ihn umhergehen und Gott loben;',
        10: 'da erkannten sie ihn, weil er es war, der für das Almosen an der Schönen Pforte des Tempels gesessen hatte, und sie wurden erfüllt mit Verwunderung und Erstaunen über das, was ihm passiert war.',
        11: 'Während er nun Petrus und Johannes festhielt, lief das ganze Volk bei ihnen zusammen in der Säulenhalle, die „Hallen Salomos“genannt wird.',
        12: 'Als nun Petrus das sah, antwortete er dem Volk: „Männer von Israel, was wundert ihr euch darüber, oder was starrt ihr uns an, als hätten wir aus eigener Kraft oder Frömmigkeit gemacht, dass er umhergeht?',
        13: 'Der Gott Abrahams und der Gott Isaaks und der Gott Jakobs, der Gott unserer Väter, hat seinen Knecht Jesus verherrlicht, den ihr verraten und vor Pilatus verleugnet habt, nachdem jener entschieden hatte, ihn freizulassen.',
        14: 'Ihr hingegen habt den Heiligen und Gerechten verleugnet und habt verlangt, dass man euch einen Mörder schenkt,',
        15: 'aber den Urheber des Lebens habt ihr getötet. Ihn hat Gott von den Toten auferweckt, wovon wir Zeugen sind.',
        16: 'Und durch den Glauben an seinen Namen hat sein Name diesen [Mann], den ihr seht und kennt, stark gemacht und der Glaube, der durch ihn [besteht], hat ihm vor euch allen diese völlige Gesundheit gegeben.',
        17: 'Und jetzt, Brüder, weiß ich, dass ihr – wie auch eure Fürsten – aus Unwissenheit gehandelt habt.',
        18: 'Gott aber hat auf diese Weise erfüllt, was er zuvor durch den Mund aller Propheten verkündet hat: dass sein Gesalbter leiden würde.',
        19: 'Tut also Buße und kehrt um, damit eure Sünden getilgt werden,',
        20: 'sodass Zeiten der Erholung vom Angesicht des Herrn kommen und er den euch vorherbestimmten Gesalbten Jesus sendet,',
        21: 'den der Himmel bis zu den Zeiten der Wiederherstellung aller [Dinge] aufnehmen muss, von denen Gott durch den Mund seiner heiligen Propheten von jeher gesprochen hat.',
        22: 'Mose hat ja gesagt: ‚Einen Propheten wird euch der Herr, euer Gott, von euren Brüdern auferstehen lassen, wie mich! Ihm sollt ihr in allem gehorchen, was auch immer er zu euch sagt.',
        23: 'Und es wird sein: Jede Seele, die jenem Propheten nicht gehorcht, wird aus dem Volk ausgerottet werden.‘',
        24: 'Aber auch alle Propheten seit Samuel und denen danach … sie alle haben von diesen Tagen geredet und verkündet.',
        25: 'Ihr seid die Söhne der Propheten und des Bundes, den Gott mit euren Vorfahren geschlossen hat, als er zu Abraham sagte: „Und durch deine Nachkommenschaft werden alle Völker der Erde gesegnet werden.“',
        26: 'Für euch zuerst hat Gott seinen Knecht auferstehen lassen und ihn gesandt, um euch zu segnen, während jeder sich von seiner Bosheit abkehrt.“',
    },
    4: {
        1: 'Während sie nun zum Volk redeten, traten ihnen die Priester und der Hauptmann des Tempels und die Sadduzäer entgegen',
        2: 'und waren empört, weil sie das Volk lehrten und in Jesus die Auferstehung von den Toten verkündeten,',
        3: 'und sie legten die Hände an sie, und sie stellten sie bis zum nächsten [Tag] unter Bewachung, denn es war bereits Abend.',
        4: 'Aber viele von denen, die das Wort gehört hatten, kamen zum Glauben, und die Zahl der Männer stieg auf etwa 5.000.',
        5: 'Es geschah aber am ‹nächsten Tag›, dass sich ihre Fürsten und Ältesten und Schriftgelehrten in Jerusalem versammelten',
        6: '(auch Hannas der Oberpriester und Kajaphas und Johannes und Alexander und wer alles von oberpriesterlichem Geschlecht war),',
        7: 'und nachdem sie sie in die Mitte gestellt hatten, erkundigten sie sich: „Mit welcher Kraft oder in wessen Namen habt ihr das getan?“',
        8: 'Daraufhin sagte Petrus zu ihnen, erfüllt vom heiligen Geist: „Ihr Fürsten des Volkes und ihr Ältesten,',
        9: 'wenn wir heute über die Wohltat an einem kranken Menschen verhört werden, wodurch dieser gerettet worden ist,',
        10: 'dann sei euch allen und dem ganzen Volk Israel gesagt: Im Namen von Jesus Christus, dem Nazoräer, den ihr gekreuzigt habt [und] den Gott von den Toten auferweckt hat … in diesem [Namen] steht dieser [Mann] gesund vor euch.',
        11: 'Dieser [Jesus] ist der Stein, der von euch, den Bauleuten, verachtet wurde [und] der zum Eckstein geworden ist.',
        12: 'Und es gibt in keinem anderen das Heil, denn es gibt auch keinen weiteren Namen unter dem Himmel, der unter den Menschen gegeben ist, durch den wir gerettet werden müssen.“',
        13: 'Als sie nun die Freimütigkeit von Petrus und Johannes sahen und begriffen, dass sie ungebildete Menschen und Laien waren, waren sie verwundert, und sie erkannten sie, weil sie mit Jesus [unterwegs] gewesen waren,',
        14: 'und da sie den Menschen, der geheilt worden war, bei ihnen stehen sahen, hatten sie nichts zu erwidern.',
        15: 'Aber nachdem sie ihnen befohlen hatten, sich außerhalb des Synedriums zu begeben, berieten sie miteinander',
        16: 'und sagten: „Was sollen wir mit diesen Leuten tun? Denn dass ein konkretes Zeichen durch sie geschehen ist, [ist] allen Bewohnern von Jerusalem klar, und wir können es nicht leugnen;',
        17: 'doch damit es sich nicht weiter zum Volk verbreitet, lasst uns ihnen drohen, künftig zu keinem Menschen über diesen Namen zu reden.“',
        18: 'Und nachdem sie sie gerufen hatten, befahlen sie kategorisch, sich weder [über den Vorfall] zu äußern noch über den Namen von Jesus zu lehren.',
        19: 'Petrus und Johannes aber antworteten und sagten zu ihnen: „Ob es vor Gott richtig ist, euch mehr zu gehorchen als Gott, das beurteilt [selbst]!',
        20: 'Wir sind nämlich nicht imstande, was wir gesehen und gehört haben, nicht zu erzählen.“',
        21: 'Sie aber drohten weiter und entließen sie, weil sie keinen Weg fanden, wie sie sie bestrafen könnten, [und zwar] wegen des Volkes, weil alle Gott über das Geschehene verherrlichten;',
        22: 'der Mensch, an dem dieses Zeichen der Heilung geschehen war, war nämlich mehr als vierzig Jahre [alt].',
        23: 'Nachdem sie nun entlassen worden waren, gingen sie zu den Ihren, und sie berichteten, was die Oberpriester und die Ältesten alles zu ihnen gesagt hatten.',
        24: 'Sie aber hörten es und erhoben gemeinsam [ihre] Stimme zu Gott, und sie sagten: „Herrscher, der du den Himmel und die Erde und das Meer und alles, was in ihnen [lebt], gemacht hast,',
        25: 'der du durch den heiligen Geist aus dem Mund unseres Vaters David, deines Knechts, gesagt hast: ‚Warum tobten die Nationen und schmiedeten die Völker Unnützes?',
        26: 'Die Könige der Erde standen auf und die Fürsten versammelten sich an demselben [Ort] gegen den Herrn und gegen seinen Gesalbten.‘',
        27: 'Denn tatsächlich haben sie sich in dieser Stadt versammelt gegen deinen heiligen Knecht Jesus, den du gesalbt hast: nämlich Herodes und Pontius Pilatus samt den Nationen und Völkern Israels,',
        28: 'um alles zu tun, was deine Hand und dein Entschluss vorgesehen hatte, geschehen zu lassen.',
        29: 'Und jetzt, Herr, sieh auf ihre Drohungen und ermögliche es deinen Dienern, dein Wort mit aller Freimütigkeit zu sagen,',
        30: 'während du deine Hand zur Heilung ausstreckst und Zeichen und Wunder durch den Namen deines heiligen Knechts Jesus geschehen.“',
        31: 'Und nachdem sie gebetet hatten, bebte der Ort, an dem sie sich versammelt hatten, und sie alle wurden erfüllt mit dem heiligen Geist, und sie redeten das Wort Gottes mit Freimütigkeit.',
        32: 'Aber die Schar derer, die zum Glauben kamen, war ein Herz und eine Seele, und auch nicht einer sagte, dass irgendetwas von seinem Besitz [ausschließlich] ihm gehöre, sondern sie hatten alles gemeinsam.',
        33: 'Und mit großer Kraft legten die Apostel das Zeugnis von der Auferstehung des Herrn Jesus ab, und große Gnade war auf ihnen allen.',
        34: 'Denn es gab auch nicht einen Bedürftigen unter ihnen; denn alle, die Eigentümer von Ländereien oder Häusern waren, verkauften sie und brachten die Erlöse der verkauften [Objekte],',
        35: 'und sie legten sie zu Füßen der Apostel, und es wurde einem jeden zugeteilt, je nachdem wie jemand Bedarf hatte.',
        36: 'Josef aber, der von den Aposteln [mit Beinamen] Barnabas gerufen wurde (das bedeutet übersetzt: Sohn der Ermutigung), ein Levit, ‹aus Zypern gebürtig›, …',
        37: 'der besaß einen Acker, verkaufte er ihn und brachte das Geld, und er legte es zu Füßen der Apostel.',
    },
    5: {
        1: 'Ein gewisser Mann aber namens Hananias verkaufte zusammen mit Saphira, seiner Frau, ein Grundstück,',
        2: 'und er unterschlug [etwas] von dem Erlös, und [seine] Frau war eingeweiht, und er brachte einen gewissen Teil und legte ihn zu Füßen der Apostel.',
        3: 'Da sagte Petrus: „Hananias, weshalb hat der Satan dein Herz erfüllt, dass du den heiligen Geist belügst und [etwas] von dem Erlös des Ackers unterschlägst?',
        4: 'Während er [unverkauft] blieb, blieb er dir da nicht [im Besitz], und nachdem er verkauft war, stand er da [nicht] zu deiner [freien] Verfügung? Warum hast du dir in deinem Herzen diese Tat vorgenommen? Du hast nicht Menschen belogen, sondern Gott!“',
        5: 'Als nun Hananias diese Worte hörte, fiel er um und verstarb, und es kam eine große Furcht über alle, die es hörten.',
        6: 'Da standen die jüngeren [Männer] auf und wickelten ihn [in ein Leichentuch], und sie trugen ihn hinaus und begruben ihn.',
        7: 'Es geschah aber nach Verlauf von etwa drei Stunden, da kam seine Frau herein, wobei sie nicht wusste, was geschehen war.',
        8: 'Da antwortete Petrus ihr: „Sag mir, ob ihr den Acker für so viel verkauft habt?“Sie aber sagte: „Ja, für so viel.“',
        9: 'Petrus wiederum [sagte] zu ihr: „Warum ist es euch zum gemeinsamen Anliegen geworden, den Geist des Herrn zu versuchen? Siehe!, die Füße derer, die deinen Mann begraben haben, [sind] vor der Tür, und sie werden dich hinaustragen.“',
        10: 'Und augenblicklich fiel sie zu seinen Füßen um und verstarb; als aber die jungen Männer hereinkamen, stellten sie fest, [dass] sie tot [war], und sie trugen sie hinaus und begruben sie bei ihrem Mann.',
        11: 'Da kam eine große Furcht über die gesamte Gemeinde und über alle, die das hörten.',
        12: 'Durch die Hände der Apostel geschahen nun viele Zeichen und Wunder unter dem Volk. Und sie waren alle beisammen in der Säulenhalle Salomos,',
        13: 'von den Übrigen aber wagte es niemand, sich ihnen anzuschließen, doch das Volk pries sie.',
        14: 'Es wurden aber mehr hinzugefügt, die an den Herrn glaubten, Scharen von Männern und Frauen,',
        15: 'sodass man sogar die Kranken auf die Straßen hinaustrug und auf Liegen und Matten legte, damit – wenn Petrus käme – wenigstens [sein] Schatten irgendeinen von ihnen überschatte.',
        16: 'Es kam aber auch die Schar aus den Städten ringsum Jerusalem zusammen und brachten Kranke und von unreinen Geistern Geplagte, welche alle geheilt wurden.',
        17: 'Da erhoben sich der Oberpriester und alle ‹seine Leute› (das heißt, die Partei der Sadduzäer), und sie wurden von Eifersucht erfüllt,',
        18: 'und sie legten die Hände an die Apostel, und sie stellten sie unter öffentliche Bewachung.',
        19: 'Aber ein Engel des Herrn öffnete während der Nacht die Türen des Gefängnisses und führte sie hinaus und sagte:',
        20: '„Geht, und dann stellt euch hin und redet im Tempel zum Volk alle Worte dieses Lebens!“',
        21: 'Da gehorchten sie und gingen vor Tagesanbruch in den Tempel, und sie fingen an zu lehren. Als nun der Oberpriester und ‹seine Leute› ankamen, riefen sie das Synedrium und die ganze Ältestenschaft der Söhne Israels zusammen, und sie sandten [einen Boten] zum Gefängnis, damit sie gebracht werden.',
        22: 'Als nun die Tempeldiener ankamen, fanden sie sie nicht im Gefängnis; da kehrten sie zurück und erstatteten Bericht,',
        23: 'indem sie sagten: „Wir fanden das Gefängnis mit aller Sorgfalt verschlossen und die Wachen vor den Türen stehen, aber nachdem wir geöffnet hatten, fanden wir drinnen niemanden.“',
        24: 'Als nun der Hauptmann des Tempels und die Oberpriester diese Worte hörten, waren sie ihretwegen ratlos, was dies werden würde.',
        25: 'Da kam jemand und berichtete ihnen: „Siehe!, die Männer, die ihr ins Gefängnis gesteckt habt, stehen im Tempel und lehren das Volk.“',
        26: 'Daraufhin ging der Hauptmann zusammen mit den Tempeldienern los und holte sie – nicht mit Gewalt, denn sie fürchteten das Volk, dass sie gesteinigt würden.',
        27: 'Sie holten sie nun und stellten sie in das Synedrium. Und der Oberpriester befragte sie',
        28: 'und sagte: „Wir haben euch doch ausdrücklich befohlen, nicht über diesen Namen zu lehren, und siehe!, ihr habt Jerusalem mit eurer Lehre erfüllt und wollt das Blut dieses Menschen über uns bringen.“',
        29: 'Da antworteten Petrus und die Apostel und sagten: „Man muss Gott mehr gehorchen als den Menschen.',
        30: 'Der Gott unserer Vorfahren hat Jesus auferweckt, den ihr umgebracht habt, indem ihr ihn ans Holz gehängt habt.',
        31: 'Ihn hat Gott als Anführer und Retter zu seiner Rechten erhöht, um Israel Buße und Vergebung der Sünden zu gewähren.',
        32: 'Und wir sind Zeugen dieser Dinge, auch der heilige Geist, den Gott denen gegeben hat, die ihm gehorchen.“',
        33: 'Diejenigen aber, die das hörten, waren erbost und beschlossen, sie zu töten.',
        34: 'Da stand im Synedrium ein gewisser Pharisäer namens Gamaliël auf, ein beim ganzen Volk angesehener Experte in Gesetzesfragen, und befahl, die Leute kurz nach draußen zu tun,',
        35: 'und er sagte zu ihnen: „Ihr Männer von Israel, seht euch bei diesen Leuten vor, was ihr zu tun gedenkt.',
        36: 'Denn vor diesen Tagen erhob sich Theudas und behauptete, dass er selbst jemand sei; mit ihm verbündete sich eine Zahl von etwa vierhundert Männern. Er wurde getötet, und alle, die ihm vertrauten, zerliefen sich und wurden bedeutungslos.',
        37: 'Nach ihm erhob sich Judas der Galiläer in den Tagen der Registrierung, und er brachte das Volk hinter sich; auch er ist umgekommen und alle, die von ihm überzeugt waren, wurden zerstreut.',
        38: 'Und jetzt sage ich euch: Haltet euch von diesen Leuten fern und lasst sie [gewähren]! Denn wenn dieses Vorhaben oder dieses Werk von Menschen stammt, dann wird es sich auflösen,',
        39: 'aber wenn es von Gott ist, dann werdet ihr sie nicht auflösen können, sonst werdet ihr noch als Widersacher Gottes befunden.“Da stimmten sie ihm zu,',
        40: 'und nachdem sie die Apostel herbeigerufen hatten, schlugen sie sie und befahlen ihnen, nicht über den Namen von Jesus zu reden, und dann ließen sie sie frei.',
        41: 'Sie gingen also freudestrahlend aus der Gegenwart des Synedriums, weil sie werterachtet worden waren, um des Namens [Jesu] willen entehrt zu werden.',
        42: 'Und sie hörten nicht auf, jeden Tag im Tempel und von Haus zu Haus zu lehren und Jesus als den Gesalbten zu verkünden.',
    },
    6: {
        1: 'In diesen Tagen nun, als die Jünger zahlreicher wurden, entstand ein Gemurre der Hellenisten gegen die Hebräer, weil ihre Witwen bei der täglichen Essensausgabe ständig übersehen wurden.',
        2: 'Da riefen die zwölf [Apostel] die Schar der Jünger herbei und sagten: „Es ist nicht in Ordnung, dass wir Tische bedienen und dabei das Wort Gottes vernachlässigen.',
        3: 'Seht euch nun um, Geschwister, nach sieben Männern von euch – mit einem guten Leumund versehen, voll des Geistes und der Weisheit –, die wir für diese Aufgabe einsetzen sollen;',
        4: 'wir hingegen werden am Gebet und am Dienst des Wortes festhalten.“',
        5: 'Und die Rede fand vor der ganzen Schar Zustimmung, und sie wählten Stephanus aus, einen Mann voll des Glaubens und des heiligen Geistes, und Philippus und Prochorus und Nikanor und Timon und Parmenas und Nikolaus, einen Proselyten aus Antiochia,',
        6: 'die sie vor die Apostel stellten, und betend legten sie ihnen die Hände auf.',
        7: 'Und das Wort Gottes wuchs ständig an und die Zahl der Jünger in Jerusalem mehrte sich rasant, und eine große Menge der Priester war dem Glauben gehorsam.',
        8: 'Stephanus aber, voll der Gnade und der Kraft, tat große Wunder und Zeichen unter dem Volk.',
        9: 'Da erhoben sich einige aus der sogenannten „Synagoge der Libertiner und Kyrenäer und Alexandriner“sowie von denen aus Kilikia und Asia und diskutierten mit Stephanus,',
        10: 'aber sie waren nicht imstande, der Weisheit und dem Geist, mit dem er redete, [etwas] entgegenzusetzen.',
        11: 'Daraufhin stifteten sie Männer an, die sagten: „Wir haben ihn lästerliche Worte gegen Mose und Gott reden hören.“',
        12: 'Und sie wiegelten das Volk und die Ältesten und die Schriftgelehrten auf, und sie überfielen und verschleppten ihn, und sie brachten ihn in das Synedrium.',
        13: 'Und sie stellten falsche Zeugen auf, die sagten: „Dieser Mensch hört nicht auf, Worte gegen diese heilige Stätte und das Gesetz zu reden;',
        14: 'wir haben ihn nämlich sagen hören, dass dieser Jesus der Nazoräer diese Stätte zerstören wird und die Bräuche verändern wird, die uns Mose überliefert hat.“',
        15: 'Und alle, die im Synedrium saßen, richteten den Blick auf ihn und sahen sein Angesicht wie das Angesicht eines Engels [glänzen].',
    },
    7: {
        1: 'Da sagte der Oberpriester: „Verhalten sich diese [Dinge] so?“',
        2: 'Er aber sagte: „Männer, Brüder und Väter, hört zu! Der Gott der Herrlichkeit ist unserem Vater Abraham erschienen, als er in Mesopotamia war, bevor er in Haran wohnte,',
        3: 'und er sagte zu ihm: ‚Geh aus deinem Land und aus deiner Verwandtschaft und geh in das Land, das ich dir zeigen will.“',
        4: 'Daraufhin ging er aus dem Land der Chaldäer fort und wohnte in Haran nieder. Und von dort – nachdem sein Vater gestorben war – siedelte er ihn in dieses Land um, in dem ihr nun wohnt,',
        5: 'und er gab ihm darin kein Erbe, auch nicht die Breite eines Fußes, aber er versprach, es ihm zum Eigentum zu geben, und seiner Nachkommenschaft mit ihm, obwohl er kein Kind hatte.',
        6: 'Da redete Gott folgendermaßen: ‚Seine Nachkommenschaft wird ein Gast sein in einem fremden Land, und man wird sie versklaven und vierhundert Jahre lang misshandeln;',
        7: 'Und die Nation, der sie als Sklaven dienen werden, werde ich richten‘, sagte Gott. ‚Und danach werden sie herauskommen, und sie werden mir dienen an diesem Ort.‘',
        8: 'Und er gab ihm den Bund der Beschneidung; und so zeugte er Isaak, und er beschnitt ihn am achten Tag, und Isaak [zeugte] Jakob, und Jakob die zwölf Stammväter.',
        9: 'Und die Stammväter waren eifersüchtig auf Josef und verkauften ihn nach Ägypten. Und Gott war mit ihm,',
        10: 'und er rettete ihn aus allen seinen Bedrängnissen, und er gab ihm Gnade und Weisheit gegenüber Pharao, dem König Ägyptens, und er stellte ihn als Herrscher über Ägypten und über sein gesamtes Haus.',
        11: 'Da kam eine Hungersnot und eine große Bedrängnis über ganz Ägypten und Kanaan, und unsere Vorfahren fanden keine Nahrung.',
        12: 'Als nun Jakob hörte, dass in Ägypten Getreide vorhanden sei, sandte er zunächst unsere Väter aus.',
        13: 'Und beim zweiten [Mal] gab sich Josef seinen Brüdern zu erkennen, und die Familie Josefs wurde dem Pharao vorgestellt.',
        14: 'Da sandte Josef [eine Nachricht] und beorderte Jakob, seinen Vater, und die ganze Sippe, im [Ganzen] fünfundsiebzig Personen.',
        15: 'Und Jakob ging hinunter nach Ägypten, und er selbst und unsere Väter starben,',
        16: 'Und sie wurden nach Sichem überführt und in das Grab gelegt, das Abraham für eine Summe Silbermünzen von den Söhnen Hamors in Sichem gekauft hatte.',
        17: 'Aber wie sich die Zeit der Verheißung näherte, die Gott dem Abraham offengelegt hatte, wuchs das Volk und vermehrte sich in Ägypten,',
        18: 'bis sich ein anderer König über Ägypten erhob, der Josef nicht kannte.',
        19: 'Dieser übervorteilte unseren Volksstamm und zwang unsere Vorfahren, ihre Säuglinge auszusetzen, damit sie nicht am Leben blieben.',
        20: 'In dieser Zeit wurde Mose geboren, und er war Gott angenehm. Er wurde drei Monate lang im Haus des Vaters aufgezogen;',
        21: 'als er nun ausgesetzt wurde, hob ihn die Tochter des Pharao auf und zog ihn für sich selbst zum Sohn auf.',
        22: 'Und Mose wurde in aller Weisheit Ägyptens erzogen, und er war fähig in seinen Worten und Werken.',
        23: 'Als für ihn nun ein Zeitraum von vierzig [Jahren] erfüllt war, kam es auf sein Herz, seine Brüder, die Israeliten, aufzusuchen.',
        24: 'Und als er sah, dass jemand ungerecht behandelt wurde, verteidigte und rächte er den Misshandelten, indem er den Ägypter niederschlug.',
        25: 'Nun meinte er, seine Brüder würden verstehen, dass Gott ihnen durch seine Hand Rettung schenkt; sie aber verstanden es nicht.',
        26: 'Und am folgenden Tag erschien er ihnen, während sie kämpften, und er versöhnte sie zum Frieden, indem er sagte: ‚Männer, ihr seid Brüder! Wieso behandelt ihr einander ungerecht?‘',
        27: 'Derjenige aber, der den Nächsten ungerecht behandelte, schubste ihn und sagte: ‚Wer hat dich als Fürst und Schiedsrichter über uns eingesetzt?',
        28: 'Willst du mich etwa töten, wie du gestern den Ägypter getötet hast?‘',
        29: 'Da floh Mose bei dieser Rede, und er wurde Gast im Land Midian, wo er zwei Söhne zeugte.',
        30: 'Und als vierzig Jahre erfüllt waren, erschien ihm in der Wüste des Berges Sinai ein Engel in der Flamme eines ‹brennenden Dornbusches›.',
        31: 'Mose aber sah es und staunte beim Anblick, und als er herantrat, um nachzusehen, da erging die Stimme des Herrn:',
        32: '‚Ich [bin] der Gott deiner Väter, der Gott Abrahams und Isaaks und Jakobs. Mose aber wurde besorgt und wagte es nicht nachzusehen.',
        33: 'Da sagte der Herr zu ihm: ‚Löse die Sandale von deinen Füßen, denn der Ort, auf dem du stehst, ist heiliger Boden.',
        34: 'Ich habe die Misshandlung meines Volkes, das in Ägypten [ist], mit eigenen Augen gesehen, und ihr Seufzen habe ich gehört, und ich bin herabgestiegen, um sie herauszureißen. Und jetzt komm, ich will dich nach Ägypten senden.‘',
        35: 'Diesen Mose, den sie verleugneten, indem sie sagten: ‚Wer hat dich als Fürsten und Schiedsrichter eingesetzt?‘, den hat Gott als Fürsten und als Erlöser gesandt, zusammen mit der [helfenden] Hand des Engels, der ihm in dem Busch erschien.',
        36: 'Er führte sie hinaus, indem er Wunder und Zeichen tat im Land Ägypten und am Roten Meer und in der Wüste, vierzig Jahre lang.',
        37: 'Er ist der Mose, der zu den Söhnen Israels sagte: ‚Einen Propheten wie mich wird euch Gott aus euren Brüdern auferstehen lassen.‘',
        38: 'Er ist es, der in der Versammlung in der Wüste bei dem Engel war, der auf dem Berg Sinai zu ihm redete, und mit unseren Vätern. Er empfing lebendige Aussprüche, um sie uns zu geben.',
        39: 'Ihm wollten unsere Vorfahren nicht gehorsam werden, sondern sie lehnten sich auf und wendeten sich in ihren Herzen nach Ägypten,',
        40: 'indem sie zu Aaron sagten: ‚Mach uns Götter, die uns vorausgehen werden! Denn dieser Mose, der uns aus Ägypten herausgeführt hat … wir wissen nicht, was ihm passiert ist.‘',
        41: 'Und sie fertigten in jenen Tagen ein Kalb an und brachten dem Götzenbild ein Opfer und freuten sich über die Werke ihrer Hände.',
        42: 'Da wendete sich Gott ab und überließ sie, dem Heer des Himmels zu dienen, wie im Buch der Propheten geschrieben steht: ‚Habt ihr mir nicht Gaben und Opfer dargebracht / vierzig Jahre lang in der Wüste, Haus Israel? /',
        43: 'Und ihr nahmt das Zelt des Moloch / und den Stern eures Gottes Räfan – / die Bilder, die ihr angefertigt habt, um sie anzubeten –, / und ich werde euch umsiedeln, jenseits von Babylon.‘',
        44: 'Unseren Vorfahren gehörte das Zelt des Zeugnisses in der Wüste, wie derjenige, der zu Mose redete, angeordnet hatte, sie anzufertigen, nach dem Vorbild, das er gesehen hatte.',
        45: 'Das führten auch unsere Väter, nachdem sie es übernommen hatten, mit Josua bei der Besitzergreifung der Nationen, die Gott vertrieb vom Angesicht unserer Väter, bis zu den Tagen Davids,',
        46: 'der Gnade fand vor Gott, und darum bat, einen Zeltplatz für das Haus Jakobs zu finden.',
        47: 'Salomo aber baute ihm ein Haus.',
        48: 'Doch der Höchste wohnt nicht in handgemachten [Häusern], wie der Prophet sagt:',
        49: '‚Der Himmel [ist] für mich ein Thron, / die Erde aber ein Schemel meiner Füße; / welches Haus werdet ihr für mich bauen, spricht der Herr, / oder was [ist] der Ort meiner Ruhe? /',
        50: 'Hat nicht meine Hand dies alles gemacht?‘',
        51: 'Ihr Halsstarrigen und an Herzen und Ohren Unbeschnittenen, ihr widersteht andauernd dem heiligen Geist – wie unsere Väter, so auch ihr!',
        52: 'Welchen der Propheten haben eure Väter nicht verfolgt? Und sie töteten diejenigen, die zuvor über das Kommen des Gerechten berichteten, dessen Verräter und Mörder ihr jetzt geworden seid,',
        53: 'die ihr das Gesetz auf Anweisung der Engel erhalten und dann nicht befolgt habt.“',
        54: 'Als sie nun diese [Dinge] hörten, wurden ihre Herzen erbost, und sie knirschten die Zähne gegen ihn.',
        55: 'Aber weil er voll des heiligen Geistes war, richtete er den Blick in den Himmel und sah die Herrlichkeit Gottes und Jesus zur Rechten Gottes stehen,',
        56: 'und er sagte: „Siehe!, ich sehe die Himmel geöffnet und den Menschensohn zur Rechten Gottes stehen.“',
        57: 'Da schrien sie mit lauter Stimme und hielten sich ihre Ohren zu, und sie fielen gemeinsam über ihn her,',
        58: 'und nachdem sie ihn aus der Stadt hinausgeworfen hatten, steinigten sie ihn. Und die Zeugen legten ihre Gewänder zu den Füßen eines jungen Mannes, der Saulus genannt wurde,',
        59: 'und sie steinigten Stephanus, der betete und sagte: „Herr Jesus, nimm meinen Geist auf!“',
        60: 'Da ging er auf die Knie und rief mit lauter Stimme: „Herr, halte ihnen diese Sünde nicht vor!“Und nachdem er dies gesagt hatte, entschlief er.',
    },
    8: {
        1: 'Saulus aber stimmte seiner Ermordung zu. An jenem Tag entstand nun eine große Verfolgung gegen die Gemeinde in Jerusalem, sie alle aber wurden zerstreut in die Gegenden von Judäa und Samaria, außer den Aposteln.',
        2: 'Fromme Männer bestatteten aber Stephanus, und sie hielten eine große Wehklage über ihn.',
        3: 'Saulus aber drangsalierte die Gemeinde: Er betrat Haus für Haus, verschleppte sowohl Männer als auch Frauen und übergab sie ans Gefängnis.',
        4: 'Diejenigen also, die verstreut waren, gingen umher und verkündeten das Wort.',
        5: 'Philippus aber ging hinab in die Stadt Samarias und predigte ihnen Christus.',
        6: 'Und die Menschenmengen achteten gemeinsam auf das, was von Philippus gesagt wurde, indem sie zuhörten und die Zeichen sahen, die er tat.',
        7: 'Denn viele von denen, die unreine Geister hatten, schrien mit lauter Stimme und gingen fort, aber viele Gelähmte und Lahme wurden geheilt.',
        8: 'Da entstand große Freude in jener Stadt.',
        9: 'Es befand sich aber bereits ein gewisser Mann namens Simon in der Stadt, der trieb Magie und erstaunte das Volk von Samaria, indem er behauptete, selbst jemand Großes zu sein.',
        10: 'Dem hingen alle an, von Klein bis Groß, und sagten: „Dieser [Mann] ist die Kraft Gottes, die man die ‚Große‘nennt.“',
        11: 'Nun hingen sie ihm an, weil er sie lange Zeit mit den Zaubereien erstaunt hatte.',
        12: 'Aber als sie Philippus glaubten, der die gute Nachricht über das Reich Gottes und den Namen von Jesus Christus verkündete, ließen sie sich taufen, sowohl Männer als auch Frauen.',
        13: 'Aber auch Simon selbst glaubte, und nachdem er sich hatte taufen lassen, hielt er sich an Philippus, und als er Zeichen und große Wunderkräfte geschehen sah, war er erstaunt.',
        14: 'Als nun die Apostel in Jerusalem hörten, dass Samaria das Wort Gottes empfangen hatte, sandten sie Petrus und Johannes zu ihnen,',
        15: 'die hinabstiegen und für sie beteten, sodass sie den heiligen Geist erhielten.',
        16: '(Er war nämlich noch auf keinen von ihnen gefallen, sondern sie waren nur auf den Namen des Herrn Jesus getauft worden.)',
        17: 'Daraufhin legten sie ihnen die Hände auf, und sie erhielten den heiligen Geist.',
        18: 'Als nun Simon sah, dass durch das Auflegen der Hände der Apostel der Geist gegeben wird, bot er ihnen Geld an',
        19: 'und sagte: „Gebt auch mir diese Vollmacht, damit, wem auch immer ich die Hände auflege, den heiligen Geist erhält.“',
        20: 'Petrus aber sagte zu ihm: „Dein Geld sei mit dir ins Verderben, weil du gemeint hast, die Gabe Gottes [sei] durch Geld zu erwerben!',
        21: 'Dir gehört weder Anteil noch Anrecht in dieser Sache, denn dein Herz ist nicht aufrichtig vor Gott.',
        22: 'Tu also Buße von dieser deiner Bosheit und bitte den Herrn, ob dir das Ansinnen deines Herzens vielleicht vergeben wird,',
        23: 'denn ich sehe, du bist in bitterer Galle und Fesseln der Ungerechtigkeit.“',
        24: 'Da antwortete Simon und sagte: „Bittet ihr für mich zum Herrn, damit nichts über mich kommt, wovon ihr gesprochen habt.“',
        25: 'Nachdem sie also Zeugnis abgelegt und das Wort der Herrn gesagt hatten, kehrten sie nach Jerusalem um und verkündeten vielen Dörfern der Samariter die gute Nachricht.',
        26: 'Aber ein Engel des Herrn redete zu Philippus und sagte: „Steh auf und geh nach Süden, auf dem Weg, der von Jerusalem nach Gaza hinabführt; der ist verlassen.“',
        27: 'Und er stand auf und ging. Und siehe!, [da war] ein Mann, ein Äthiopier, ein Eunuch, ein Minister der Kandake (der Königin von Äthiopien), der ihren ganzen Schatz verwaltete; der war nach Jerusalem gekommen, um anzubeten.',
        28: 'Und er war auf der Heimreise und saß auf seinem Wagen und las den Propheten Jesaja.',
        29: 'Da sagte der Geist zu Philippus: „Geh hin und hänge dich an diesen Wagen!“',
        30: 'Philippus lief nun hin und hörte ihn den Propheten Jesaja lesen, und er sagte: „Verstehst du überhaupt, was du liest?“',
        31: 'Er aber sagte: „Wie könnte ich denn, wenn mich niemand anleiten wird?“Und er lud Philippus ein, aufzusteigen und sich zu ihm zu setzen.',
        32: 'Und der Abschnitt der Schrift, den er las, war folgender: „Wie ein Schaf zur Schlachtbank wurde er geführt, und wie ein Lamm vor dem, der es schert, stumm [ist], so öffnet er nicht seinen Mund.',
        33: 'In seiner Erniedrigung wurde sein Recht genommen; wer wird seine Generation beschreiben? Denn sein Leben wird von der Erde genommen.“',
        34: 'Da antwortete der Eunuch dem Philippus und sagte: „Ich frage dich, über wen sagt der Prophet dies? Über sich selbst oder über jemand anderes?“',
        35: 'Da öffnete Philippus seinen Mund und, indem er bei dieser Schrift begann, verkündete er ihm Jesus.',
        36: 'Aber wie sie auf dem Weg gingen, kamen sie an ein Gewässer, und der Eunuch sagt: „Siehe!, [da ist] Wasser, was hindert mich getauft zu werden?“',
        38: 'Und er befahl, den Wagen anzuhalten, und sie stiegen beide hinunter in das Wasser – sowohl Philippus als auch der Eunuch – und er taufte ihn.',
        39: 'Als sie nun aus dem Wasser hinaufstiegen, ergriff der Geist des Herrn den Philippus, und der Eunuch sah ihn nicht mehr, denn er ging seinen Weg und freute sich.',
        40: 'Philippus hingegen wurde in Aschdod angetroffen, und er zog umher und verkündete allen Städten die gute Nachricht, bis er nach Cäsarea kam.',
    },
    9: {
        1: 'Saulus wiederum, der immer noch Nötigung und Mord gegen die Jünger des Herrn schnaubte, ging zum Oberpriester und',
        2: 'erbat von ihm Briefe an die Synagogen in Damaskus, damit er, wenn er welche findet, die zu dem „Weg“gehören – sowohl Männer als auch Frauen –, sie gefesselt nach Jerusalem führen könnte.',
        3: 'Während der Reise geschah es nun, dass er sich Damaskus näherte und plötzlich umstrahlte ihn ein Licht aus dem Himmel,',
        4: 'und er fiel auf die Erde und hörte eine Stimme, die zu ihm sagte: „Saul, Saul, warum verfolgst du mich?“',
        5: 'Da sagte er: „Wer bist du, Herr?“Er wiederum [sagte]: „Ich bin Jesus, den du verfolgst.',
        6: 'Steh jedoch auf und geh in die Stadt, dann wird man dir sagen, was du tun sollst.“',
        7: 'Die Männer aber, die mit ihm unterwegs waren, standen sprachlos da, weil sie zwar die Stimme hörten, aber niemanden sahen.',
        8: 'Da wurde Saulus von der Erde aufgerichtet, aber als er seine Augen öffnete, sah er nichts. Da leiteten sie ihn und führten ihn nach Damaskus.',
        9: 'Und er konnte drei Tage lang nicht sehen, und er aß weder noch trank er.',
        10: 'Es gab nun einen gewissen Jünger in Damaskus namens Hananias, und der Herr sagte zu ihm in einer Vision: „Hananias!“Er aber sagte: „Siehe!, [hier bin] ich, Herr.“',
        11: 'Der Herr aber [sagte] zu ihm: „Steh auf und geh in die sogenannte ‚Gerade Straße‘, und suche im Haus des Juda [nach jemandem] namens Saulus von Tarsus; denn siehe!, er betet,',
        12: 'und er hat einen Mann namens Hananias in einer Vision gesehen, der hereinkommt und ihm die Hände auflegt, damit er wieder sieht.“',
        13: 'Da antwortete Hananias: „Herr, ich habe von Vielen über diesen Mann gehört, wie viel Schlechtes er deinen Heiligen in Jerusalem angetan hat;',
        14: 'und er hat bereits eine Vollmacht von den Oberpriestern, alle zu fesseln, die deinen Namen anrufen.“',
        15: 'Da sagte der Herr zu ihm: „Geh, weil er für mich ein auserwähltes Werkzeug ist, um meinen Namen sowohl vor Nationen als auch Könige und die Kinder Israels zu tragen.',
        16: 'Denn ich werde ihm zeigen, was er alles für meinen Namen leiden muss.“',
        17: 'Da ging Hananias los und betrat das [besagte] Haus, und er legte die Hände auf ihn und sagte: „Saul, Bruder, der Herr hat mich gesandt – Jesus, der dir auf dem Weg, den du kamst, erschienen ist –, damit du wieder siehst und mit dem heiligen Geist erfüllt wirst.“',
        18: 'Und sofort fiel es wie Schuppen von seinen Augen, und er sah wieder und stand auf und ließ sich taufen;',
        19: 'und er nahm Essen [zu sich] und stärkte sich. Er war aber einige Tage bei den Jüngern in Damaskus.',
        20: 'Und sofort predigte er Jesus in den Synagogen, dass dieser der Sohn Gottes sei.',
        21: 'Da waren alle erstaunt, die zuhörten, und sie sagten: „Ist er nicht dieser, der in Jerusalem die zugrunde gerichtet hat, die diesen Namen anrufen, und zu diesem [Zweck] hierher gekommen war, um sie gefesselt zu den Oberpriestern zu führen?“',
        22: 'Saulus aber kam nach und nach zu Kräften und irritierte die Judäer, die in Damaskus wohnten, weil er bewies, dass dieser der Gesalbte sei.',
        23: 'Als nun etliche Tage erfüllt waren, planten die Judäer, ihn umzubringen;',
        24: 'aber ihr Komplott wurde Saulus bekannt. Und sie bewachten auch die Tore – sowohl tagsüber als auch nachts –, um ihn umzubringen.',
        25: 'Da nahmen ihn die Jünger eines Nachts und ließen ihn durch die Mauer herab, indem sie ihn in einem Korb absenkten.',
        26: 'Als er nun in Jerusalem ankam, versuchte er, sich den Jüngern anzuschließen, und sie alle fürchteten ihn, weil sie nicht glaubten, dass er ein Jünger sei.',
        27: 'Barnabas aber nahm ihn auf und führte ihn zu den Aposteln, und er erzählte ihnen, wie er auf dem Weg den Herrn gesehen hatte und dass er zu ihm geredet hatte und wie er in Damaskus freimütig im Namen von Jesus gesprochen hatte.',
        28: 'Und er ging bei ihnen in Jerusalem ein und aus, wobei er freimütig im Namen des Herrn redete;',
        29: 'und er redete und diskutierte mit den Hellenisten, sie aber versuchten, ihn umzubringen.',
        30: 'Und als die Brüder das bemerkten, brachten sie ihn hinab nach Cäsarea und sandten ihn fort nach Tarsus.',
        31: 'Die Gemeinde in ganz Judäa und Galiläa und Samaria hatte also Frieden und wurde auferbaut, und weil sie in der Furcht des Herrn und in der Ermutigung des heiligen Geistes lebte, vermehrte sie sich.',
        32: 'Nun geschah es, dass Petrus, während er überall hinreiste, auch zu den Heiligen hinabging, die Lydda bewohnten.',
        33: 'Und dort fand er einen gewissen Mann namens Äneas, der seit acht Jahren auf einer Matte lag [und] der gelähmt war.',
        34: 'Und Petrus sagte zu ihm: „Äneas, Jesus Christus heilt dich! Steh auf und mache dein Bett selbst!“Und sofort stand er auf.',
        35: 'Und alle, die Lydda und Saron bewohnten, sahen ihn, welche zum Herrn umkehrten.',
        36: 'In Joppe wiederum gab es eine gewisse Jüngerin namens Tabita (sie heißt übersetzt: Dorkas). Sie war voller guter Werke und Almosen, die sie verrichtete.',
        37: 'Es geschah nun in jenen Tagen, dass sie krank wurde und starb. Nachdem man sie nun gewaschen hatte, legte man sie in ein Gästezimmer.',
        38: 'Weil nun Lydda nahe bei Joppe war, sandten die Jünger, nachdem sie gehört hatten, dass Petrus dort war, zwei Männer zu ihm und forderten ihn auf: „Zögere nicht, bis zu uns zu kommen!“',
        39: 'Da erhob sich Petrus und begleitete sie. Den führten sie, als er ankam, hinauf zu dem Gästezimmer, und alle Witwen traten an ihn heran, wobei sie weinten und ihm die Hemden und Gewänder zeigten, die Dorkas alle angefertigt hatte, während sie bei ihnen war.',
        40: 'Petrus warf aber alle hinaus und ging auf die Knie und betete, und zu dem Leichnam gewandt sagte er: „Tabita, steh auf!“Sie aber öffnete ihre Augen, und als sie Petrus sah, setzte sie sich auf.',
        41: 'Er reichte ihr aber eine Hand und ließ sie aufstehen, und nachdem er die Heiligen und die Witwen gerufen hatte, präsentierte er sie lebend.',
        42: 'Es wurde aber in ganz Joppe bekannt, und viele vertrauten auf den Herrn.',
        43: 'Und es geschah, dass er etliche Tage in Joppe bei einem gewissen Simon dem Gerber blieb.',
    },
    10: {
        1: 'Nun [lebte] in Cäsarea ein gewisser Mann namens Kornelius, ein Zenturio aus der sogenannten „Italischen Kohorte“,',
        2: 'fromm und gottesfürchtig mit seinem ganzen Haus, der dem Volk viele Almosen gab und fortwährend zu Gott betete.',
        3: 'Etwa um die neunte Stunde des Tages sah er in einer Vision deutlich einen Engel Gottes zu sich hinkommen und zu ihm sagen: „Kornelius!“',
        4: 'Er aber starrte ihn an und wurde ängstlich und sagte: „Was ist, Herr?“Da sagte er zu ihm: „Deine Gebete und deine Almosen sind emporgestiegen zum Gedenken vor Gott.',
        5: 'Und jetzt schicke Männer nach Joppe und bestelle einen gewissen Simon, der [mit Beinamen] Petrus gerufen wird.',
        6: 'Dieser wird von einem gewissen Simon dem Gerber beherbergt, dem ein Haus am Meer gehört.“',
        7: 'Als nun der Engel, der zu ihm geredet hatte, gegangen war, rief er zwei der Hausdiener und einen frommen Soldaten von denen, die für ihn bereitstanden,',
        8: 'und nachdem er ihnen alles beschrieben hatte, sandte er sie nach Joppe.',
        9: 'Am folgenden [Tag] nun, während jene unterwegs waren und sich der Stadt näherten, stieg Petrus auf das Dach hinauf, um zu beten, etwa zur sechsten Stunde.',
        10: 'Da wurde er hungrig und wollte essen. Während sie nun [etwas] zubereiteten, kam eine Trance über ihn,',
        11: 'und er sieht den Himmel sich öffnen und ein Behältnis – etwas wie ein großes Leinentuch – herabkommen, das an vier Enden auf der Erde abgesetzt wird;',
        12: 'darin befanden sich alle [möglichen] Vierbeiner und Reptilien der Erde und Vögel des Himmels.',
        13: 'Und eine Stimme richtete sich an ihn: „Steh auf, Petrus, schlachte und iss!“',
        14: 'Petrus aber sagte: „Auf gar keinen Fall, Herr, weil ich noch nie etwas Unsauberes und Unreines gegessen habe.“',
        15: 'Da [richtete sich] die Stimme erneut – zum zweiten [Mal] – an ihn: „Was Gott rein erklärt hat, sollst du nicht unsauber nennen.“',
        16: 'Und das geschah dreimal, dann wurde das Behältnis sofort in den Himmel hinaufgenommen.',
        17: 'Während nun Petrus bei sich ratlos war, was die Vision, die er gesehen hatte, bedeuten möge, siehe!, [da] fragten sich die Männer, die von Kornelius gesandt worden waren, zum Haus von Simon durch und standen vor dem Tor,',
        18: 'und nachdem sie gerufen hatten, erkundigten sie sich, ob Simon, der [mit Beinamen] Petrus gerufen wird, dort übernachtete.',
        19: 'Während Petrus nun über die Vision nachdachte, sagte der Geist zu ihm: „Siehe!, drei Männer suchen dich.',
        20: 'Steh doch auf und steig herab, und dann geh zusammen mit ihnen und zweifele nichts an, weil ich sie gesandt habe.“',
        21: 'Da stieg Petrus zu den Männern herab und sagte: „Siehe!, ich bin es, den ihr sucht. Was [ist] der Grund, weswegen ihr da seid?“',
        22: 'Sie aber sagten: „Kornelius, ein Zenturio, ein gerechter und gottesfürchtiger Mann, und von der ganzen Nation der Judäer bezeugt, wurde von einem heiligen Engel instruiert, dich in sein Haus zu bestellen und Worte von dir zu hören.“',
        23: 'Nachdem er sie also hereingebeten hatte, beherbergte er sie. Am folgenden [Tag] nun stand er auf und ging zusammen mit ihnen fort, und einige der Brüder aus Joppe begleiteten ihn.',
        24: 'Und am folgenden [Tag] kam er nach Cäsarea, Kornelius aber erwartete sie und rief seine Verwandten und engsten Freunde zusammen.',
        25: 'Und es geschah, wie Petrus hineinging, da begrüßte ihn Kornelius, fiel zu Füßen und betete an.',
        26: 'Petrus aber richtete ihn auf und sagte: „Steh auf! Auch ich selbst bin [nur] ein Mensch.“',
        27: 'Und während er sich mit ihm unterhielt, ging er hinein und entdeckt, dass viele zusammengekommen waren.',
        28: 'Und er sagte zu ihnen: „Ihr glaubt, dass es einem judäischen Mann verboten ist, sich einem Fremden anzuschließen oder auf ihn zuzugehen; aber mir hat Gott gezeugt, keinen Menschen unsauber oder unrein zu nennen.',
        29: 'Darum kam ich auch ohne Widerrede, als ich bestellt wurde. Also erkundige ich mich, aus welchem Anlass ihr mich bestellt habt?“',
        30: 'Und Kornelius sagte: „Vor vier Tagen zu dieser Stunde, die neunte, betete ich in meinem Haus, und siehe!, ein Mann in einer hellen Robe stand vor mir',
        31: 'und sagt: ‚Kornelius, dein Gebet wurde erhört und deine Almosen wurden vor Gott erinnert.',
        32: 'Schick also [eine Nachricht] nach Joppe und bestelle Simon, der [mit Beinamen] Petrus gerufen wird; dieser übernachtet im Haus von Simon dem Gerber am Meer.',
        33: 'Also schickte ich umgehend zu dir und du hast gut gehandelt und bist gekommen. Jetzt sind wir also alle vor Gott anwesend, um alles zu hören, was dir vom Herrn aufgetragen ist.“',
        34: 'Da öffnete Petrus den Mund und sagte: „Tatsächlich begreife ich [jetzt], dass Gott nicht parteiisch ist,',
        35: 'sondern dass ihm in jedem Volk willkommen ist, wer ihn fürchtet und Gerechtigkeit bewirkt.',
        36: 'Das Wort, das er den Israeliten gesandt hat, um durch Jesus Christus Frieden zu verkünden … dieser ist Herr über alle.',
        37: 'Ihr kennt die Sache, die in ganz Judäa passiert ist, angefangen in Galiläa mit der Taufe, die Johannes gepredigt hat:',
        38: 'Jesus von Nazaret, wie Gott ihn mit heiligem Geist und Kraft gesalbt hat, der umherging und dabei Gutes bewirkte und alle heilte, die vom Teufel unterdrückt wurden, weil Gott mit ihm war.',
        39: 'Und wir [sind] Zeugen von allem, was er getan hat, sowohl in dem Gebiet der Judäer als auch in Jerusalem. Den brachten sie auch um, indem sie ihn ans Holz hängten.',
        40: 'Diesen hat Gott am dritten Tag auferweckt und ermöglichte es, dass er sichtbar wurde,',
        41: 'nicht allem Volk, sondern uns, die wir zuvor von Gott als Zeugen auserwählt worden sind, welche zusammen mit ihm gegessen und getrunken haben, nachdem er von den Toten auferstanden war.',
        42: 'Und er hat uns befohlen, dem Volk zu predigen und zu bezeugen, dass er es sei, der von Gott zum Richter der Lebenden und der Toten bestimmt ist.',
        43: 'Über ihn bezeugen all die Propheten, dass durch seinen Namen jeder, der an ihn glaubt, Vergebung der Sünden erhält.“',
        44: 'Noch während Petrus diese Worte redete, fiel der heilige Geist auf alle, die das Wort hörten.',
        45: 'Und es staunten alle Gläubigen aus der Beschneidung, die Petrus begleitet hatten, dass auch auf die [heidnischen] Völker die Gabe des heiligen Geistes ausgegossen worden war;',
        46: 'denn sie hörten sie in [fremden] Sprachen reden und Gott preisen. Daraufhin antwortete Petrus:',
        47: '„Kann etwa jemand das Wasser verwehren, sodass diese [Menschen] nicht getauft werden, welche den heiligen Geist erhalten haben wie auch wir?“',
        48: 'Da ordnete er an, dass sie im Namen von Jesus Christus getauft werden. Daraufhin baten sie ihn, einige Tage zu bleiben.',
    },
    11: {
        1: 'Nun hörten die Apostel und die Geschwister, die in Judäa waren, dass auch die [heidnischen] Völker das Wort Gottes annahmen.',
        2: 'Und als Petrus nach Jerusalem hinaufstieg, zweifelten die aus der Beschneidung an ihm',
        3: 'und sagten: „Du bist zu Männern hineingegangen, die ‹unbeschnitten waren›, und hast zusammen mit ihnen gegessen.“',
        4: 'Da begann Petrus und stellte ihnen [die Ereignisse] der Reihe nach dar und sagte:',
        5: '„Ich war in der Stadt Joppe am Beten und sah in Trance eine Vision, ein Behältnis, etwas wie ein großes Leinentuch, herabkommen an vier Enden aus dem Himmel abgesetzt, und es kam bis zu mir.',
        6: 'Nachdem ich einen Blick hinein geworfen hatte, dachte ich nach, und ich sah die Vierbeiner der Erde und die Tiere und die Reptilien und die Vögel der Himmel.',
        7: 'Da hörte ich auch eine Stimme, die zu mir sagte: ‚Steh auf, Petrus, schlachte und iss!‘',
        8: 'Und ich sagte: ‚Auf gar keinen Fall, Herr! Denn Unsauberes oder Unreines ist noch nie in meinen Mund hineingekommen.‘',
        9: 'Da antwortete die Stimme aus dem Himmel zum zweiten [Mal]: ‚Was Gott rein gemacht hat, sollst du nicht unsauber nennen.‘',
        10: 'Und das geschah dreimal, dann wurde alles wieder in den Himmel hinaufgezogen.',
        11: 'Und siehe!, prompt traten drei Männer an das Haus heran, in dem wir waren, die aus Cäsarea zu mir gesandt worden waren.',
        12: 'Da sagte mir der Geist, sie zu begleiten und nichts anzuzweifeln. Nun gingen zusammen mit mir auch diese sechs Geschwister, und wir gingen in das Haus des Mannes hinein.',
        13: 'Da berichtete er uns, wie er den Engel sah, der in seinem Haus stand und sagte: ‚Sende [eine Nachricht] nach Joppe und bestelle Simon, der [mit Beinamen] Petrus gerufen wird,',
        14: 'der wird Worte zu euch reden, durch die du gerettet werden wirst, du und dein ganzes Haus.‘',
        15: 'Und als ich zu reden begann, fiel der heilige Geist auf sie, genau wie am Anfang auch auf uns.',
        16: 'Da erinnerte ich mich an das Wort des Herrn, wie er sagte: ‚Johannes hat mit Wasser getauft, ihr hingegen werdet mit heiligem Geist taufen.‘',
        17: 'Wenn Gott ihnen also die gleiche Gabe gibt wie uns, die wir auf den Herrn Jesus Christus vertrauen, wer wäre ich – fähig, Gott abzuhalten?“',
        18: 'Als sie nun diese [Dinge] hörten, verstummten sie, und dann verherrlichten sie Gott und sagten: „Vielleicht hat Gott auch den [heidnischen] Völkern die Buße zum Leben gegeben.“',
        19: 'Diejenigen also, die von der Bedrängnis zerstreut wurden, die wegen Stephanus entstanden war, reisten bis nach Phönizien und Zypern und Antiochia und sagten niemandem das Wort, außer Judäern allein.',
        20: 'Nun waren einige von ihnen Männer aus Zypern und Kyrene, die, als sie nach Antiochia kamen, auch zu den Hellenisten redeten und den Herrn Jesus verkündeten.',
        21: 'Und die Hand des Herrn war mit ihnen und eine große Zahl, die zum Glauben kam, kehrte zum Herrn um.',
        22: 'Nun wurde der Bericht über sie in den Ohren der Gemeinde gehört, die in Jerusalem war, und sie sandten Barnabas aus, bis nach Antiochia zu reisen.',
        23: 'Als der ankam und die Gnade von Gott sah, freute er sich, und er fing an alle ermutigen, an dem Vorhaben des Herzens in dem Herrn zu bleiben,',
        24: 'weil er ein guter Mann war und voll des heiligen Geistes und des Glaubens. Und eine große Menge wurde dem Herrn hinzugefügt.',
        25: 'Und er ging fort nach Tarsus, um Saulus aufzusuchen.',
        26: 'Und als er ihn fand, führte er ihn nach Antiochia. Und es geschah, dass sie sogar ein ganzes Jahr lang in der Gemeinde zusammenkamen und eine große Menge lehrten. Und in Antiochia wurden die Jünger zum ersten Mal „Christen“genannt.',
        27: 'Nun kamen in diesen Tagen Propheten herab von Jerusalem nach Antiochia.',
        28: 'Und einer von ihnen namens Agabus stand auf und deutete durch den Geist an, dass es eine große Hungersnot auf dem gesamten Erdkreis geben würde (die sich in der Amtszeit von Klaudius ereignete hat).',
        29: 'Von den Jüngern aber – wie es jemand gut erging – entschied ein jeder von ihnen, den Geschwistern, die in Judäa wohnten, [etwas] zur Unterstützung zu schicken;',
        30: 'das taten sie auch, indem sie [ihre Hilfe] durch die Hand von Barnabas und Saulus zu den Ältesten sandten.',
    },
    12: {
        1: 'Zu jener Zeit aber legte König Herodes die Hände an einige von denen von der Gemeinde, um sie zu misshandeln.',
        2: 'Und er brachte Jakobus, den Bruder von Johannes, mit einem Schwert um.',
        3: 'Als er nun sah, dass es für die Judäer in Ordnung war, beschloss er, auch Petrus zu verhaften. (Es waren aber die Tage der ungesäuerten [Brote].)',
        4: 'Den brachte er, nachdem er ihn ebenfalls gefasst hatte, ins Gefängnis und übergab ihn an vier Einheiten von je vier Soldaten, um ihn bewachen zu lassen, weil er beabsichtigte, ihn nach dem Passa dem Volk vorzuführen.',
        5: 'Petrus wurde also im Gefängnis bewacht; von der Gemeinde wurde aber inständig für ihn zu Gott gebetet.',
        6: 'Als nun Herodes ihn vorzuladen gedachte, in jener Nacht schlief Petrus zwischen zwei Soldaten, gefesselt mit zwei Ketten; und Wächter vor der Tür bewachten das Gefängnis.',
        7: 'Und siehe!, ein Engel des Herrn stand da, und ein Licht schien in der Zelle; und indem er die Seite von Petrus schlug, weckte er ihn und sagte: „Steh schnell auf!“Und seine Ketten fielen von den Händen ab.',
        8: 'Da sagte der Engel zu ihm: „Gürte dich und binde deine Sandalen!“Da machte er es so. Und er sagt zu ihm: „Wirf dein Gewand um und folge mir!“',
        9: 'Und er ging hinaus und folgte ihm, und er wusste nicht, dass das, was durch den Engel geschah, real war, und er meinte, eine Vision zu sehen.',
        10: 'Aber nachdem sie an der ersten und zweiten Wache durchgekommen waren, kamen sie zu dem eisernen Tor, das in die Stadt führte, welches sich ihnen von selbst öffnete, und sie gingen hinaus und weiter in einer Gasse, und sofort wich der Engel von ihm.',
        11: 'Und als Petrus zu sich kam, sagte er: „Jetzt weiß ich wirklich, dass der Herr seinen Engel ausgesandt hat und mich errettet hat aus der Hand des Herodes und aus aller Erwartung des Volkes der Judäer.“',
        12: 'Und als er das merkte, ging er zu dem Haus von Maria, der Mutter des Johannes, der [mit Beinamen] Markus gerufen wird, wo etliche versammelt waren und beteten.',
        13: 'Als er nun an der Tür des Tors klopfte, ging eine Magd namens Rhode hin, um zu horchen.',
        14: 'Und als sie die Stimme von Petrus erkannte, öffnete sie vor Freude das Tor nicht, sondern lief hinein und verkündete, dass Petrus vor dem Tor steht.',
        15: 'Sie aber sagten zu ihr: „Du bist wahnsinnig!“Sie wiederum bestand darauf, dass es sich so verhielte. Sie aber sagten: „Es ist sein Engel.“',
        16: 'Petrus wiederum blieb am Klopfen. Da öffneten sie und sahen ihn, und sie staunten.',
        17: 'Da winkte [er] ihnen mit der Hand, still zu werden, und er erzählte ihnen, wie der Herr ihn aus dem Gefängnis herausgeführt hatte; und er sagte: „Berichtet Jakobus und den Geschwistern diese [Dinge]!“Und ging hinaus und ging an einen anderen Ort.',
        18: 'Als es nun Tag wurde, gab es eine nicht geringe Aufregung unter den Soldaten, was denn aus Petrus geworden sei.',
        19: 'Aber als Herodes ihn suchte und nicht fand, befragte er die Wachen und befahl, sie zu exekutieren. Und er kam von Judäa herunter nach Cäsarea und blieb [dort].',
        20: 'Er war nun wütend mit den Tyrern und Sidoniern; aber einmütig kamen sie zu ihm, und nachdem sie Blastus, den Kämmerer des Königs, überredet hatten, baten sie um Frieden, weil ihr Gebiet von dem königlichen [Land] ernährt wurde.',
        21: 'An einem festgelegten Tag hielt nun Herodes, nachdem er eine königliche Robe angezogen und sich auf den Richterstuhl gesetzt hatte, eine öffentliche Ansprache an sie,',
        22: 'aber das Volk rief: „Gottes Stimme und nicht die eines Menschen!“',
        23: 'Und prompt schlug ihn ein Engel des Herrn nieder, weil er Gott nicht die Ehre gegeben hatte, und er wurde von Würmern zerfressen und verstarb.',
        24: 'Aber das Wort Gottes wuchs und vermehrte sich.',
        25: 'Aber Barnabas und Saulus kehrten zurück nach Jerusalem, nachdem sie den Dienst erfüllt hatten, wobei sie Johannes, der [mit Beinamen] Markus gerufen wurde, mitnahmen.',
    },
    13: {
        1: 'Nun gab es in Antiochia, in der [dort] befindlichen Gemeinde, Propheten und Lehrer, und zwar Barnabas und Simeon, der [mit Beinamen] Niger genannt wird, und Luzius den Kyrenäer sowie Manaën, ein Jugendfreund des Tetrarchen Herodes, sowie Saulus.',
        2: 'Während sie nun dem Herrn dienten und fasteten, sagte der heilige Geist: „Sondert mir jetzt Barnabas und Saulus aus für das Werk, zu dem ich sie berufen habe.“',
        3: 'Daraufhin – nachdem sie gefastet und gebetet und ihnen die Hände aufgelegt hatten – stellten sie sie frei.',
        4: 'Sie also gingen – losgeschickt vom heiligen Geist – hinab nach Seleukia, und von dort segelten sie nach Zypern,',
        5: 'und in Salamis angekommen, verkündeten sie das Wort Gottes in den Synagogen der Judäer. Sie hatten aber auch Johannes als Gehilfen dabei.',
        6: 'Als sie nun die gesamte Insel bis nach Paphos durchquert hatten, trafen sie einen gewissen Mann, einen Zauberer, einen judäischen falschen Propheten, der den Namen Barjesus [trug].',
        7: 'Der war [per du] mit dem Prokonsul Sergius Paulus, einem klugen Mann. Dieser rief Barnabas und Saulus zu sich und verlangte, das Wort Gottes zu hören.',
        8: 'Da widerstand ihnen Elymas der Magier (denn so lässt sich sein Name übersetzen) und versuchte, den Prokonsul vom Glauben abzubringen.',
        9: 'Saulus aber, der auch Paulus [hieß], wurde vom heiligen Geist erfüllt, richtete den Blick auf ihn und',
        10: 'sagte: „Oh du [Mann] voll aller List und aller Skrupellosigkeit du Sohn des Teufels, du Feind aller Gerechtigkeit, wirst du nicht aufhören, die geraden Wege des Herrn durcheinanderzubringen?',
        11: 'Und jetzt, siehe!, die Hand des Herrn [ist] gegen dich, und du wirst blind sein und die Sonne eine Weile nicht sehen.“Und augenblicklich fielen Nebel und Dunkelheit auf ihn, und er ging umher und suchte Leute, die ihn an der Hand führten.',
        12: 'Daraufhin – als der Prokonsul das Geschehene sah – glaubte er, weil er über die Lehre vom Herrn erstaunt war.',
        13: 'Als nun ‹Paulus und seine Leute› von Paphos aufbrachen, gingen nach Perga in Pamphylia. Johannes aber trennte sich von ihnen und kehrte zurück nach Jerusalem.',
        14: 'Sie aber gingen von Perga und trafen in Antiochia Pisidia ein, und sie gingen am Tag des Sabbats in die Synagoge und setzten sich.',
        15: 'Nach der Lesung des Gesetzes und der Propheten nun sandten die Synagogenvorsteher [eine Nachricht] zu ihnen und sagten: „Männer, Brüder, wenn es unter euch irgendein Wort der Ermutigung an das Volk gibt, dann sagt es!“',
        16: 'Da stand Paulus auf und machte mit der Hand Zeichen und sagte: „Männer von Israel und die ihr Gott fürchtet, hört [mit] zu!',
        17: 'Der Gott dieses Volkes Israel hat unsere Vorfahren erwählt, und er hat das Volk erhöht in der Fremde, im Land Ägypten, und er hat sie mit erhobenem Arm von dort herausgeführt,',
        18: 'und für einen Zeitraum von etwa vierzig Jahren ernährte er sie in der Wüste,',
        19: 'und er vernichtete sieben [heidnische] Völker im Land Kanaan und vermachte ihnen ihr Land,',
        20: 'etwa vierhundertfünfzig Jahre lang. Und danach gab er Richter bis zum Propheten Samuel.',
        21: 'Von da an erbaten sie einen König, und Gott gab ihnen Saul, den Sohn des Kisch, einen Mann aus dem Stamm Benjamins, für vierzig Jahre.',
        22: 'Und nachdem er ihn abgesetzt hatte, erweckte er ihnen David zum König, über den er auch sagte und bezeugte: ‚Ich habe David gefunden, den [Sohn] des Isaï, einen Mann nach meinem Herzen, der meinen ganzen Willen tun wird.‘',
        23: 'Aus dessen Nachkommenschaft hat Gott gemäß [seiner] Verheißung einen Retter für Israel gebracht – Jesus –,',
        24: 'nachdem Johannes vor seinem Auftreten dem ganzen Volk Israel eine Taufe der Buße verkündet hatte.',
        25: 'Während nun Johannes seine Mission erfüllte, sagte er: ‚Was denkt ihr, dass ich sei? Ich bin es nicht, sondern siehe!, nach mir kommt einer, dessen Sandale von den Füßen zu lösen ich nicht würdig bin.‘',
        26: 'Männer, Brüder, Söhne aus dem Stamm Abrahams und diejenigen unter euch, die Gott fürchten: Zu uns wurde das Wort dieser Rettung ausgesandt.',
        27: 'Denn die Bewohner in Jerusalem und ihre Fürsten haben – weil sie es nicht erkannten – auch die Stimmen der Propheten erfüllt, die an jedem Sabbat gelesen werden, indem sie ihn verurteilten.',
        28: 'Und obwohl sie nicht den geringsten Anlass zur Todesstrafe fanden, baten sie Pilatus, ihn zu töten.',
        29: 'Als nun alles vollbracht war, was über ihn geschrieben steht, holten sie ihn von dem Holz und legten ihn in eine Grabhöhle.',
        30: 'Gott aber hat ihn von den Toten auferweckt!',
        31: 'Er erschien über viele Tage denen, die zusammen mit ihm von Galiläa nach Jerusalem hinaufgestiegen waren [und] die jetzt seine Zeugen gegenüber dem Volk sind.',
        32: 'Und wir verkünden euch die Verheißung, die zu den Vorfahren kam:',
        33: 'dass Gott diese [Verheißung] uns, deren Kindern, erfüllt hat, indem er Jesus auferstehen ließ, wie auch im zweiten Psalm geschrieben steht: ‚Mein Sohn bist du, ich habe dich heute gezeugt.‘',
        34: 'Dass er ihn aber von den Toten auferstehen ließ, sodass er nicht mehr zur Verwesung zurückkehren würde, hat er folgendermaßen gesagt: ‚Ich werde euch die heiligen, verlässlichen [Statuten] Davids geben.‘',
        35: 'Darum sagt er auch an anderer [Stelle]: ‚Du wirst nicht zulassen, dass dein Heiliger Verwesung sieht.‘',
        36: 'Denn David ist ja, nachdem er in seiner eigenen Generation dem Willen Gottes gedient hat, entschlafen und wurde zu seinen Vorfahren beigesetzt und hat Verwesung gesehen;',
        37: 'aber der, den Gott auferweckt hat, hat keine Verwesung gesehen.',
        38: 'Es soll euch also bekannt sein, Männer, Brüder, dass euch durch diesen [Mann] Vergebung der Sünden verkündigt wird und von allem, wovon ihr durch das Gesetz des Mose gerechtfertigt werden nicht konntet,',
        39: 'wird durch ihn jeder gerechtfertigt, der glaubt.',
        40: 'Seht also zu, dass euch nicht überkommt, was durch die Propheten gesagt ist:',
        41: '‚Seht, ihr Verächter, und staunt und verschwindet, weil ich in euren Tagen ein Werk bewirke – ein Werk, das ihr bestimmt nicht glaubt, selbst wenn es euch jemand erklärt.‘“',
        42: 'Während sie nun hinausgingen, baten sie, dass ihnen diese Worte am nächsten Sabbat gesagt würden.',
        43: 'Und nachdem sich die Synagoge aufgelöst hatte, folgten viele der Judäer und der gottesfürchtigen Proselyten Paulus und Barnabas, welche ihnen zuredeten und sie davon überzeugten, in der Gnade Gottes zu bleiben.',
        44: 'Als nun der Sabbat kam, versammelte sich beinahe die ganze Stadt, um das Wort des Herrn zu hören.',
        45: 'Als nun die Judäer die Menschenmengen sahen, wurden sie von Neid erfüllt und widersprachen dem, was von Paulus gesagt wurden, indem sie lästerten.',
        46: 'Sowohl Paulus als auch Barnabas redeten freimütig und sagten: „Es war notwendig, dass das Wort Gottes zuerst euch gesagt wird; weil ihr es ablehnt und euch selbst des ewigen Lebens nicht würdig haltet, siehe!, deshalb wenden wir uns den [heidnischen] Völkern zu!',
        47: 'Denn so hat es uns der Herr geboten: ‚Ich habe dich zum Licht der Völker bestimmt, damit du zur Rettung beiträgst bis ans Ende der Erde.‘“',
        48: 'Als nun die [heidnischen] Völker das hörten, freuten sie sich, und sie verherrlichten das Wort des Herrn, und es kamen alle zum Glauben, die zum ewigen Leben bestimmt waren.',
        49: 'Da wurde das Wort des Herrn quer durch das gesamte Gebiet verbreitet.',
        50: 'Die Judäer aber stifteten die angesehenen gottesfürchtigen Frauen, und die bedeutenden [Männer] der Stadt, an und erweckten eine Verfolgung gegen Paulus und Barnabas und vertrieben sie aus ihrem Gebiet.',
        51: 'Sie aber, nachdem sie den Staub der Füße gegen sie abgeschüttelt hatten, gingen nach Ikonion.',
        52: 'Und die Jünger waren von Freude und vom heiligen Geist erfüllt.',
    },
    14: {
        1: 'Es geschah nun in Ikonion, dass sie gemeinsam in die Synagoge der Judäer hineingingen und so redeten, dass sowohl von den Judäern als auch von den Griechen eine große Menge glaubten.',
        2: 'Aber die ungläubigen Judäer weckten und hetzten die Seelen der Heiden gegen die Brüder auf.',
        3: 'Sie blieben also einige Zeit und sprachen freimütig über den Herrn, der über das Wort seiner Gnade bezeugte, indem er Zeichen und Wunder durch ihre Hände geschehen ließ.',
        4: 'Da wurde die Menge der Stadt gespalten, und einige waren zusammen mit den Judäern, andere zusammen mit den Aposteln.',
        5: 'Als nun ein Begehren entstand, sowohl vonseiten der Heiden als auch der Judäer, zusammen mit ihren Fürsten, sie zu verhöhnen und zu steinigen,',
        6: 'bemerkten sie es und flohen in die Städte Lykaonias: Lystra und Derbe und die Umgebung,',
        7: 'und dort verkündeten sie das Evangelium.',
        8: 'Und in Lystra saß ein gewisser Mann, kraftlos in den Füßen, von ‹Geburt an› lahm, der noch nie gelaufen war.',
        9: 'Dieser hörte Paulus reden; als der den Blick auf ihn richtete und sah, dass er Glauben hatte, gerettet zu werden,',
        10: 'sagte er mit lauter Stimme: „Steh gerade auf deine Füße!“Und er sprang auf und ging umher.',
        11: 'Und als die Menschenmengen sahen, was Paulus getan hatte, erhoben sie ihre Stimme und sagten auf Lykaonisch: „Die Götter sind den Menschen gleich geworden und zu uns herabgestiegen.“',
        12: 'Und sie nannten Barnabas „Zeus“, Paulus aber „Hermes“, weil er der Wortführer war.',
        13: 'Und der Priester [vom Tempel] des Zeus, der vor der Stadt war, brachte Bullen und Kränze an die Tore und wollte sie gemeinsam mit den Menschenmengen opfern.',
        14: 'Als nun die Apostel Barnabas und Paulus das hörten, zerrissen sie ihre Gewänder und rannten hinaus in die Menschenmenge, wobei sie schrien',
        15: 'und sagten: „Männer, warum tut ihr das? Auch wir sind Menschen, die wie ihr von Emotionen getrieben [sind], und verkünden euch, von diesen nutzlosen [Dingen] zu dem lebendigen Gott umzukehren, der den Himmel und die Erde und das Meer und alles, was in ihnen [ist], gemacht hat.',
        16: 'Der ließ in den vergangenen Generationen alle [heidnischen] Völker ihre Wege gehen;',
        17: 'und dennoch hat er sich nicht unbezeugt gelassen, weil er Gutes getan hat, indem er euch vom Himmel her Regen und fruchtbare Jahreszeiten gab [und] eure Herzen mit Essen und Fröhlichkeit erfüllte.“',
        18: 'Und obwohl sie diese [Dinge] sagten, brachten sie die Menschenmengen, [nur] mit Mühe dazu, ihnen nicht zu opfern.',
        19: 'Da kamen Judäer aus Antiochia und Ikonion an, und nachdem sie die Menschenmengen überredet und Paulus gesteinigt hatten, schleiften sie ihn aus der Stadt heraus, da sie meinten, er sei gestorben.',
        20: 'Aber als die Jünger ihn umgaben, stand er auf und ging in die Stadt hinein. Und am folgenden [Tag] ging er zusammen mit Barnabas fort nach Derbe.',
        21: 'Und nachdem sie jener Stadt die gute Nachricht verkündet und etliche zu Jüngern gemacht hatten, kehrten sie zurück nach Lystra und nach Ikonion und nach Antiochia,',
        22: 'wobei sie die Seelen der Jünger stärkten [und] sie ermahnten, im Glauben zu bleiben und dass wir durch viele Bedrängnisse in das Reich Gottes eingehen müssen.',
        23: 'Nachdem sie ihnen nun von Gemeinde zu Gemeinde Älteste ausgesucht hatten, beteten sie mit Fasten und vertrauten sie dem Herrn an, an den sie geglaubt hatten.',
        24: 'Und nachdem sie Pisidia durchquert hatten, kamen sie nach Pamphylien,',
        25: 'und als sie in Perge das Wort gesagt hatten, stiegen sie hinab nach Attalia,',
        26: 'und von dort segelten sie nach Antiochia, wo sie der Gnade Gottes übergeben worden waren für das Werk, das sie erfüllt hatten.',
        27: 'Und nachdem sie angekommen waren und die Gemeinde versammelt hatten, berichteten sie, was Gott mit ihnen alles getan hatte und dass er den [heidnischen] Völkern eine Tür des Glaubens geöffnet hatte.',
        28: 'Und sie verbrachten nicht wenig Zeit mit den Jüngern.',
    },
    15: {
        1: 'Und einige, die von Judäa herabgekommen waren, lehrten die Brüder: „Wenn ihr nicht mit dem Brauch des Mose beschnitten werdet, könnt ihr nicht gerettet werden.“',
        2: 'Weil nun eine nicht geringe Aufruhr und Debatte durch Paulus und Barnabas gegen sie entstand, bestimmten sie, dass Paulus und Barnabas und einige andere von ihnen anlässlich dieser strittigen Frage zu den Aposteln und Ältesten nach Jerusalem hinaufsteigen sollten.',
        3: 'Sie wurden also von der Gemeinde auf die Reise geschickt und durchquerten sowohl Phönizien als auch Samaria, wobei sie ausführlich von der Bekehrung der [heidnischen] Völker erzählten, und sie machten allen Brüdern große Freude.',
        4: 'Und in Jerusalem angekommen, wurden sie von der Gemeinde und den Aposteln und den Ältesten empfangen, und sie berichteten, was Gott alles mit ihnen getan hatte.',
        5: 'Da erhoben sich einige von denen aus der Partei der Pharisäer, die gläubig geworden waren, und sagten: „Es ist notwendig, sie zu beschneiden und ihnen zu befehlen, das Gesetz des Mose zu halten.“',
        6: 'Da versammelten sich die Apostel und die Ältesten, um über diese Angelegenheit zu beraten.',
        7: 'Als nun eine große Debatte entstand, stand Petrus auf und sagte zu ihnen: „Männer, Brüder, ihr wisst, dass Gott in früheren Tagen unter euch gewählt hat, dass die [heidnischen] Völker durch meinen Mund das Wort der guten Nachricht hören und glauben.',
        8: 'Und Gott, der Herzenskenner, hat es bezeugt, indem er ihnen den heiligen Geist gab, so wie auch uns,',
        9: 'und keinen Unterschied zwischen uns und ihnen machte, weil er ihre Herzen durch den Glauben reinigte.',
        10: 'Warum also versucht ihr jetzt Gott, indem ihr ein Joch auf den Hals der Jünger legt, das weder unsere Vorfahren noch wir imstande waren zu tragen?',
        11: 'Sondern wir glauben, durch die Gnade des Herrn Jesus gerettet zu werden – genauso auch jene!“',
        12: 'Da schwieg die ganze Menge, und sie hörten Barnabas und Paulus beschreiben, was Gott alles an Zeichen und Wunder unter den [heidnischen] Völkern durch sie getan hatte.',
        13: 'Und nachdem sie verstummt waren, antwortete Jakobus und sagte: „Männer, Brüder, hört mir zu!',
        14: 'Simeon hat beschrieben, wie Gott das erste [Mal] dafür gesorgt hat, von den [heidnischen] Völkern ein Volk für seinen Namen zu nehmen.',
        15: 'Und damit stimmen die Worte der Propheten überein, wie geschrieben steht:',
        16: '‚Danach werde ich zurückkehren und die Hütte Davids wieder aufbauen, die gefallen ist, und was von ihr niedergerissen ist, werde ich aufbauen und sie aufrichten,',
        17: 'damit die übrigen Menschen den Herrn aufsuchen, und alle [heidnischen] Völker, über denen mein Name ausgerufen worden ist, spricht der Herr, der diese [Dinge] tut,',
        18: 'bekannt seit jeher.“',
        19: 'Daher meine ich, [wir sollten] denen von den [heidnischen] Völkern, die zu Gott umkehren, keinen Kummer bereiten,',
        20: 'sondern ihnen schreiben, sich von den Verunreinigungen der Götzen und der Unzucht und des Erstickten und des Blutes fernzuhalten.',
        21: 'Denn Mose hat seit vielen Generationen in jeder Stadt diejenigen, die ihn predigen, weil er an jedem Sabbat in den Synagogen vorgelesen wird.“',
        22: 'Daraufhin beschlossen die Apostel und die Ältesten samt der ganzen Gemeinde, Männer von ihnen auszuwählen und zusammen mit Paulus und Barnabas nach Antiochia zu schicken – Judas, der [mit Beinamen] Barsabbas genannt wird, und Silas, führende Männer unter den Brüdern –',
        23: 'und durch ihre Hand zu schreiben: „Die Apostel und die Ältesten, Brüder. An die Geschwister in ganz Antiochia und Syria und Kilikia, die aus den [heidnischen] Völkern [stammen]: Seid gegrüßt!',
        24: 'Weil wir gehört haben, dass einige von uns ausgegangen sind und euch verunsichert haben, indem sie eure Seelen mit Worten verwirren, zu denen wir keine Veranlassung gegeben haben,',
        25: 'schien es uns gut, nachdem wir einstimmig geworden sind, ausgewählte Männer zusammen mit unseren geliebten [Brüdern] Barnabas und Paulus zu euch zu schicken –',
        26: 'Menschen, die ihr Leben für den Namen unseres Herrn Jesus Christus gegeben haben.',
        27: 'Wir haben also Judas und Silas abgesandt, die dasselbe auch selbst durch eine Ansprache verkünden.',
        28: 'Denn es schien dem heiligen Geist und uns gut, euch keine größere Last aufzuerlegen außer diesen notwendigen [Dingen]:',
        29: 'sich von Götzen Geopfertem und Blut und Ersticktem und Unzucht fernzuhalten. Wenn ihr euch selbst davor hütet, werdet ihr gut handeln. Lebt wohl!“',
        30: 'Sie wurden also ausgesandt und kamen hinab nach Antiochia, und nachdem sie die Menge versammelt hatten, übergaben sie den Brief.',
        31: 'Und als sie ihn verlasen, freuten sie sich über die Ermutigung.',
        32: 'Judas und Silas, die auch selbst Propheten waren, ermutigten und stärkten die Geschwister durch eine lange Ansprache,',
        33: 'und nachdem sie eine Weile verbracht hatten, wurden sie mit Frieden von den Brüdern zu denen entlassen, die sie gesandt hatten.',
        35: 'Paulus und Barnabas aber blieben in Antiochia, wobei sie mit noch vielen anderen das Wort des Herrn lehrten und verkündeten.',
        36: 'Nach einigen Tagen sagte Paulus nun zu Barnabas: „Lass uns nun zurückkehren und die Geschwister in jeder Stadt besuchen, in denen wir das Wort des Herrn verkündet haben, [um zu sehen], wie es ihnen geht.“',
        37: 'Barnabas aber wollte auch Johannes, der [mit Beinamen] Markus genannt wird, mitnehmen;',
        38: 'Paulus hingegen bestand darauf, den nicht mitzunehmen, der von ihnen aus Pamphylia weggegangen war und sie nicht zu dem Werk begleitet hatte.',
        39: 'Da entstand eine heftige Auseinandersetzung, sodass sie sich voneinander trennten, und zwar nahm Barnabas Markus, um nach Zypern zu segeln,',
        40: 'Paulus hingegen wählte Silas und reiste ab, nachdem ihm die Gnade des Herrn von den Geschwistern übergeben worden war.',
        41: 'Und er durchquerte Syria und Kilikia und stärkte die Gemeinden.',
    },
    16: {
        1: 'Er gelangte nun auch nach Derbe und nach Lystra. Und siehe!, dort war ein gewisser Jünger namens Timotheus, der Sohn einer gläubigen, judäischen Frau, aber eines griechischen Vaters,',
        2: 'der wurde von den Geschwistern in Lystra und Ikonion mit einem guten Leumund versehen.',
        3: 'Paulus wollte, dass dieser zusammen mit ihm fortreist, und er nahm und beschnitt ihn um der Judäer willen, die an jenen Orten waren; denn sie alle wussten, dass sein Vater ein Grieche war.',
        4: 'Wie sie nun die Städte durchquerten, vermittelten sie ihnen, die Anordnungen zu befolgen, die von den Aposteln und Ältesten in Jerusalem entschieden worden waren.',
        5: 'So wurden die Gemeinden im Glauben gestärkt, und wurden von Tag zu Tag zahlreicher.',
        6: 'Sie durchquerten nun Phrygia und das galatische Gebiet, weil wir vom heiligen Geist daran gehindert wurden, das Wort in Asia zu sagen.',
        7: 'Als sie nun Richtung Mysia kamen, versuchten sie, nach Bithynia zu reisen, aber der Geist von Jesus ließ sie nicht.',
        8: 'Und nachdem sie Mysia passiert hatten, stiegen sie hinab nach Troas.',
        9: 'Und während der Nacht erschien Paulus eine Vision: Ein Mann aus Makedonia stand da und bat ihn und sagte: „Komm herüber nach Makedonia und hilf uns!“',
        10: 'Als er nun die Vision gesehen hatte, versuchten wir sofort, nach Makedonia abzureisen, da wir schlussfolgerten, dass Gott uns gerufen hatte, ihnen die gute Nachricht zu verkünden.',
        11: 'Da brachen wir von Troas auf und segelten direkt nach Samothrake, und am folgenden [Tag] nach Neapolis,',
        12: 'und von dort nach Philippi, welches eine bedeutende Stadt in [jenem] Teil von Makedonia ist, eine Kolonie. Wir verbrachten nun einige Tage in dieser Stadt.',
        13: 'Und am Sabbattag gingen wir hinaus vor das Tor an einen Fluss, wo wir vermuteten, dass Gebet stattfindet, und nachdem wir uns gesetzt hatten, redeten wir zu den versammelten Frauen.',
        14: 'Und eine gewisse Frau namens Lydia, eine Purpurhändlerin aus der Stadt Thyatira, die Gott anbetete, hörte zu; deren Herz öffnete der Herr, sodass sie achtgab, was von Paulus gesagt wurde.',
        15: 'Und als sie und ihr Haus sich taufen ließen, bat sie und sagte: „Wenn ihr zu dem Urteil gelangt seid, dass ich dem Herrn treu bin, dann kommt in mein Haus und bleibt!“Und sie bedrängte uns.',
        16: 'Es geschah nun, als wir zum Gebet gingen, da begegnete uns irgendeine Magd, die den Geist Python hatte [und] welche ihren Besitzern viel Profit einbrachte, indem sie wahrsagte.',
        17: 'Während sie Paulus und uns verfolgte, schrie sie und sagte: „Diese Leute sind Knechte des höchsten Gottes, die uns den Weg des Heils verkünden.“',
        18: 'Und dies tat sie über viele Tage. Da wurde Paulus verärgert und zu dem Geist gewandt sagte er: „Ich befehle dir im Namen von Jesus Christus, von ihr wegzugehen!“Und er ging in diesem Moment weg.',
        19: 'Als nun ihre Besitzer sahen, dass die Hoffnung ihrer Profite weggegangen war, ergriffen sie Paulus und Silas und schleppten sie zum Marktplatz vor die Fürsten,',
        20: 'und als sie sie zu den Hauptmännern brachten, sagten sie: „Diese Leute beunruhigen unsere Stadt, weil sie Judäer sind,',
        21: 'und sie verkünden Sitten, die uns nicht erlaubt sind, anzunehmen noch zu tun, weil wir Römer sind.“',
        22: 'Und die Menschenmenge verbündete sich gegen sie, und die Hauptmänner zerrissen ihre Gewänder und befahlen, sie zu schlagen.',
        23: 'Und nachdem sie ihnen viele Hiebe erteilt hatten, warfen sie sie ins Gefängnis und wiesen den Kerkermeister an, sie sicher zu verwahren.',
        24: 'Der warf sie, weil er einen solchen Befehl erhalten hatte, in das innere Gefängnis und befestigte ihre Füße in einem Holzblock.',
        25: 'Gegen Mitternacht nun beteten Paulus und Silas und sangen zu Gott, und die Gefangenen lauschten ihnen.',
        26: 'Da entstand plötzlich ein großes Erdbeben, sodass die Fundamente des Gefängnisses erschüttert wurden, und augenblicklich wurden alle Türen geöffnet und die Fesseln von allen wurden gelöst.',
        27: 'Als nun der Kerkermeister wach wurde und die geöffneten Türen des Gefängnisses sah, zog er das Schwert und wollte sich selbst umbringen, weil er meinte, die Gefangenen wären geflohen.',
        28: 'Da rief Paulus mit lauter Stimme und sagte: „Tu dir selbst nichts Schlimmes an, denn wir sind alle hier!“',
        29: 'Und nachdem er Lichter erbeten hatte, eilte er hinein, und zitternd fiel er vor Paulus und Silas nieder.',
        30: 'Und nachdem er sie nach draußen geführt hatte, sagte er: „Ihr Herren, was muss ich tun, damit ich gerettet werde?“',
        31: 'Sie aber sagten: „Vertraue auf den Herrn Jesus, dann wirst du gerettet werden, du und dein Haus!“',
        32: 'Und sie sagten ihm das Wort des Herrn, zusammen mit allen, die in seinem Haus [waren].',
        33: 'Und er nahm sie in jener Stunde der Nacht zu sich und wusch [die Wunden] von den Hieben, und er selbst und alle, die zu ihm [gehörten], wurden augenblicklich getauft.',
        34: 'Und er führte sie hinauf in [sein] Haus und stellte ihnen einen [gedeckten] Tisch bereit, und er jubelte mit seinem ganzen Haus, weil er an Gott gläubig geworden war.',
        35: 'Aber als es Tag wurde, sandten die Hauptmänner die Vollstrecker und sagten: „Lass jene Leute frei!“',
        36: 'Da berichtete der Kerkermeister diese Worte an Paulus: „Die Hauptmänner haben [eine Nachricht] gesandt, dass ihr entlassen wurdet. Nun zieht also fort und geht in Frieden!“',
        37: 'Paulus aber sagte zu ihnen: „Nachdem sie uns öffentlich ohne Verurteilung geschlagen haben – Leute, die Römer sind –, haben sie uns ins Gefängnis geworfen; und jetzt werfen sie uns heimlich hinaus? So nicht! Sondern sie selbst sollen kommen und uns hinausführen!“',
        38: 'Und die Vollstrecker berichteten den Hauptmännern diese Worte. Da fürchteten sie sich, als sie hörten, dass sie Römer sind.',
        39: 'Und sie kamen und redeten ihnen zu, und sie führten sie hinaus und baten sie, die Stadt zu verlassen.',
        40: 'Und als sie aus dem Gefängnis herauskamen, gingen sie zu Lydia, und als sie die Geschwister, sahen, ermutigten sie sie, und dann gingen sie fort.',
    },
    17: {
        1: 'Nachdem sie nun durch Amphipolis und Apollonia gereist waren, kamen sie nach Thessalonich, wo eine Synagoge der Judäer war.',
        2: 'Und wie es Paulus gewohnt war, ging er zu ihnen hinein, und an drei Sabbattagen diskutierte er mit ihnen von den Schriften her,',
        3: 'indem er ihnen aufschloss und darlegte, dass der Gesalbte leiden und von den Toten auferstehen musste und dass dieser der Gesalbte ist – „Jesus, den ich euch verkünde.“',
        4: 'Und einige von ihnen ließen sich überzeugen und gesellten sich zu Paulus und Silas, auch von den gottesfürchtigen Griechen eine große Menge und von den bedeutenden Frauen nicht wenige.',
        5: 'Da ereiferten sich die Judäer und schnappten sich einige böse Männer von dem Gesindel, und sie schufen einen Mob und versetzten die Stadt in Aufruhr, und sie stürmten das Haus von Jason und versuchten, sie der Volksversammlung vorzuführen.',
        6: 'Aber als sie sie nicht fanden, schleiften sie Jason und einige Brüder vor die Regierenden der Stadt und riefen: „Die den Erdkreis aufgewiegelt haben, … diese [Leute] kommen auch hierher.',
        7: 'Die hat Jason beherbergt, und sie alle handeln entgegen der Anordnungen des Cäsars, indem sie sagen, dass ein anderer König sei: Jesus.“',
        8: 'Da verunsicherten sie die Menschenmenge und die Regierenden der Stadt, die diese [Dinge] hörten,',
        9: 'und nachdem sie eine Bürgschaft von Jason und den Übrigen genommen hatten, ließen sie sie frei.',
        10: 'Die Brüder aber schickten Paulus und Silas gleich – [noch] während der Nacht – nach Beröa fort. [Dort] angekommen gingen sie in die Synagoge der Judäer.',
        11: 'Diese aber waren wohlgesonnener als die in Thessalonich: Sie empfingen das Wort mit aller Bereitwilligkeit und untersuchten die Schriften Tag für Tag, ob sich diese [Dinge] so verhielten.',
        12: 'Viele von ihnen kamen also zum Glauben, auch von den angesehenen griechischen Frauen und Männern nicht wenige.',
        13: 'Als aber die Judäer von Thessalonich erfuhren, dass auch in Beröa das Wort Gottes von Paulus verkündet wurde, kamen sie um auch dort die Menschenmengen aufzuwiegeln und zu verunsichern.',
        14: 'Daraufhin nun sandten die Brüder Paulus gleich fort, um bis zum Meer zu gehen, Silas und Timotheus blieben aber dort.',
        15: 'Diejenigen aber, die Paulus Geleit gaben, brachten ihn bis nach Athen, und nachdem sie einen Auftrag für Silas und Timotheus erhalten hatten, [nämlich] dass sie so schnell wie möglich zu ihm kommen sollten, reisten sie ab.',
        16: 'Während Paulus sie nun in Athen erwartete, wurde sein Geist in ihm aufgewühlt, als er die Abgötterei sah, die in der Stadt herrschte.',
        17: 'Er diskutierte also in der Synagoge mit den Judäern und den Gottesfürchtigen, und wochentags auf dem Marktplatz mit den Passanten.',
        18: 'Aber auch einige der epikuräischen und stoischen Philosophen gerieten an ihn, und einige sagten: „Was will dieser Schwätzer sagen?“Andere wiederum: „Er scheint ein Verkünder fremder Gottheiten zu sein!“, weil er Jesus und die Auferstehung verkündete.',
        19: 'Und nachdem sie ihn sich gegriffen hatten, führten sie ihn auf den Areopag und sagten: „Können wir erfahren, was diese neue Lehre [ist], die von dir erwähnt wird?',
        20: 'Du bringst nämlich einige befremdliche [Dinge] zu unseren Ohren. Wir wollen also erfahren, was ‹dies zu bedeuten hat›.“',
        21: '(Nun verbrachten alle Athener und die Fremden, die zugereist waren, [ihre Zeit] mit nichts anderem, als etwas Neues zu sagen oder etwas zu hören.)',
        22: 'Da erhob sich Paulus inmitten des Areopags und sagte: „Männer von Athen, ich betrachte euch in jeder [Hinsicht] als sehr religiös.',
        23: 'Denn als ich umherging und eure Heiligtümer betrachtete, fand ich auch einen Altar, auf dem geschrieben stand: FÜR EINEN UNBEKANNTEN GOTT. Was ihr also unwissend verehrt, das verkündige ich euch:',
        24: 'Der Gott, der die Welt und alles, was darin [ist], gemacht hat, der ist Herr des Himmels und der Erde und wohnt nicht in handgemachten Tempeln,',
        25: 'noch wird er von menschlichen Händen bedient, als ob er irgendetwas benötigen würde, da er selbst allen Leben und Atem und [überhaupt] alles gibt.',
        26: 'Und er hat aus einem einzigen [Menschen] jedes Menschenvolk gemacht, damit sie auf der ganzen Erdoberfläche wohnen, wobei er festgelegte Zeiten und die Grenzen ihrer Besiedelung bestimmt hat,',
        27: 'damit sie Gott suchen, ob sie ihn vielleicht doch erahnen und finden mögen, weil er ja auch nicht fern von jedem Einzelnen von uns ist.',
        28: 'Denn in ihm leben wir und bewegen wir uns und sind wir, wie auch einige Dichter eurerseits gesagt haben: ‚Denn wir sind auch von [seinem] Geschlecht.‘',
        29: 'Weil wir also das Geschlecht Gottes sind, dürfen wir nicht meinen, das Göttliche sei Gold oder Silber oder Stein gleich, einem Denkmal der Kunst und der Erfindung des Menschen.',
        30: 'Nachdem Gott also über die Zeiten der Unwissenheit hinweggesehen hat, gebietet er jetzt den Menschen, dass alle überall Buße tun,',
        31: 'weil er einen Tag festgelegt hat, an dem er den Erdkreis in Gerechtigkeit richten wird durch einen Mann, den er bestimmt hat, und er hat allen einen Beweis geliefert, indem er ihn von den Toten hat auferstehen lassen.“',
        32: 'Als sie nun von einer Auferstehung der Toten hörten, spotteten die einen, andere sagten: „Wir werden dich darüber auch noch mal hören.“',
        33: 'So ging Paulus aus ihrer Mitte fort.',
        34: 'Einige Männer aber schlossen sich ihm an und kamen zum Glauben, unter ihnen auch Dionysius der Areopagit und eine Frau namens Damaris und weitere mit ihnen.',
    },
    18: {
        1: 'Danach verließ er Athen und kam nach Korinth.',
        2: 'Und er fand einen gewissen Judäer namens Aquila, ‹aus Pontus gebürtig›, der kurz zuvor aus Italia gekommen war, und seine Frau Priszilla – weil Klaudius angeordnet hatte, dass alle Judäer Rom verlassen sollten –, und ging zu ihnen,',
        3: 'und weil er im gleichen Handwerk war, blieb er bei ihnen und arbeitete; sie waren nämlich Zeltmacher von Beruf.',
        4: 'Er diskutierte aber in der Synagoge an jedem Sabbat, und er überzeugte Judäer und Griechen.',
        5: 'Als nun Silas und Timotheus von Makedonia herabkamen, war Paulus vom Wort in Beschlag genommen und bezeugte den Judäern, dass Jesus der Gesalbte sei.',
        6: 'Da sie aber Widerstand leisteten und lästerten, schüttelte er die Gewänder aus und sagte zu ihnen: „Euer Blut [komme] auf euren Kopf! Ich [bin] rein. Ab jetzt werde ich zu den [heidnischen] Völkern gehen!“',
        7: 'Und er zog von dort weiter und kam in das Haus von jemand namens Titius Justus, der Gott anbetete [und] dessen Haus neben der Synagoge gelegen war.',
        8: 'Krispus aber, der Synagogenvorsteher, kam mit seinem gesamten Haus zum Glauben an den Herrn; auch viele der Korinther, die zuhörten, glaubten und ließen sich taufen.',
        9: 'Da sprach der Herr in der Nacht durch eine Vision zu Paulus: „Fürchte dich nicht, sondern rede und schweige nicht!',
        10: 'Denn ich bin bei dir, und niemand wird dich angreifen, um dir zu schaden, weil mir ein großes Volk in dieser Stadt gehört.“',
        11: 'Da ließ er sich ein Jahr und sechs Monate lang nieder und lehrte unter ihnen das Wort Gottes.',
        12: 'Als nun Gallio Prokonsul von Achaja war, stellten sich die Judäer einmütig gegen Paulus, und sie führten ihn vor den Richterstuhl',
        13: 'und sagten: „Dieser [Mann] stiftet die Leute an, Gott [in einer Weise] anzubeten, die gegen das Gesetz [ist].“',
        14: 'Als nun Paulus gerade den Mund öffnen wollte, sagte Gallio zu den Judäern: „Wenn es irgendein Verbrechen oder böses Vergehen wäre, oh Judäer, dann hätte ich euch selbstverständlich angehört.',
        15: 'Aber wenn es Streitfragen über Worte und Namen und euer eigenes Gesetz sind, dann müsst ihr selbst zusehen! Ich will darüber nicht Richter sein.“',
        16: 'Dann vertrieb er sie vom Richterstuhl.',
        17: 'Da ergriffen alle den Synagogenvorsteher Sosthenes und schlugen ihn vor dem Richterstuhl; und nichts davon kümmerte Gallio.',
        18: 'Nachdem nun Paulus noch etliche Tage geblieben war, verabschiedete er sich von den Geschwistern und segelte nach Syria – und mit ihm Priszilla und Aquila –, nachdem er sich in Kenchräa den Kopf geschoren hatte, denn er hatte ein Gelübde [abgelegt].',
        19: 'Sie gelangten nun nach Ephesus, und jene ließ er dort zurück, er aber ging in die Synagoge und diskutierte mit den Judäern.',
        20: 'Aber obwohl sie ihn baten, längere Zeit zu bleiben, willigte er nicht ein,',
        21: 'sondern nachdem er sich verabschiedet und gesagt hatte: „Ich werde wieder zu euch zurückkommen, wenn Gott will“, brach er von Ephesus auf,',
        22: 'und als er in Cäsarea angelegt hatte, stieg er hinauf und grüßte die Gemeinde; [anschließend] stieg er hinab nach Antiochia.',
        23: 'Und nachdem er [dort] einige Zeit verbracht hatte, reiste er ab und durchquerte nacheinander das galatische Gebiet und Phrygia, um alle Jünger zu stärken.',
        24: 'Ein gewisser Judäer aber namens Apollos, ‹aus Alexandrien gebürtig›, ein redegewandter Mann, der in den Schriften bewandert war, traf in Ephesus ein.',
        25: 'Dieser war den Weg des Herrn unterrichtet worden und lebte im Geist; er redete und lehrte gründlich über Jesus, obwohl ihm nur die Taufe von Johannes vertraut war.',
        26: 'Und dieser begann, freimütig in der Synagoge zu reden. Nachdem sie ihn aber gehört hatten, nahmen ihn Priszilla und Aquila zu sich, und sie legten ihm den Weg Gottes [noch] gründlicher aus.',
        27: 'Als er nun nach Achaja reisen wollte, ermutigten ihn die Brüder und schrieben den Jüngern, ihn zu empfangen. [Dort] angekommen half er denen sehr, die durch die Gnade zum Glauben gekommen waren.',
        28: 'Denn energisch widerlegte er öffentlich die Judäer, indem er durch die Schriften aufzeigte, dass Jesus der Gesalbte ist.',
    },
    19: {
        1: 'Es geschah nun, während Apollos in Korinth war, dass Paulus die höher gelegenen Gegenden durchquerte und nach Ephesus hinabkam und einige Jünger fand,',
        2: 'und er sagte zu ihnen: „Habt ihr den heiligen Geist empfangen, als ihr zum Glauben gekommen seid?“Sie aber [sagten] zu ihm: „Wir haben doch noch nicht einmal gehört, dass der heilige Geist existiert!“',
        3: 'Und er sagte: „Worauf wurdet ihr dann getauft?“Sie aber sagten: „Auf die Taufe von Johannes.“',
        4: 'Da sagte Paulus: „Johannes hat mit der Taufe der Buße getauft und dem Volk gesagt, dass sie an den glauben sollten, der nach ihm komme, das heißt: an Jesus.“',
        5: 'Als sie nun das hörten, ließen sie sich auf den Namen des Herrn Jesus taufen.',
        6: 'Und als Paulus ihnen die Hände auflegte, kam der heilige Geist auf sie, und sie redeten in [fremden] Sprachen und weissagten.',
        7: 'Es waren aber insgesamt etwa zwölf Männer.',
        8: 'Da ging er in die Synagoge und redete drei Monate lang freimütig, indem er diskutierte und [die Anwesenden] hinsichtlich des Reiches Gottes überzeugte.',
        9: 'Aber als einige sich verhärteten und ungehorsam waren, sodass sie den „Weg“vor der Menge verunglimpften, hielt er sich von ihnen fern und sonderte die Jünger ab, um Tag für Tag in der Schule eines Tyrannus zu diskutieren.',
        10: 'Und dies geschah zwei Jahre lang, sodass alle, die in Asia wohnten, das Wort des Herrn hörten, sowohl Judäer als auch Griechen.',
        11: 'Und Gott tat außergewöhnliche Wunderkräfte durch die Hände von Paulus,',
        12: 'sodass man sogar Schweißtücher und Schürzen, ‹die seine Haut berührt hatten›, zu den Kranken trug und die Krankheiten von ihnen abließen und die bösen Geister weggingen.',
        13: 'Es versuchten aber auch einige der umherziehenden judäischen Exorzisten über denen, die die bösen Geister hatten, den Namen des Herrn Jesus zu nennen, indem sie sagten: „Ich beschwöre euch bei dem Jesus, den Paulus predigt.“',
        14: 'Nun gab es sieben Söhne eines gewissen Skevas, einem judäischen Oberpriester, die dies taten.',
        15: 'Da antwortete der böse Geist und sagte zu ihnen: „Jesus kenne ich und Paulus ist mir vertraut, aber wer seid ihr?“',
        16: 'Und der Mann, in dem der böse Geist war, sprang auf sie, bezwang sie allesamt und gewann gegen sie, sodass sie nackt und verwundet aus jenem Haus flohen.',
        17: 'Aber dies wurde allen bekannt, die in Ephesus wohnten, sowohl Judäern als auch Griechen, und Ehrfurcht befiel sie alle, und der Name des Herrn Jesus wurde gepriesen.',
        18: 'Und viele von denen, die zum Glauben gekommen waren, kamen, um ihre Taten zu bekennen und zu gestehen.',
        19: 'Aber etliche von denen, die Magie betrieben hatten, trugen die Bücher zusammen und verbrannten sie vor allen; und sie zählten deren Preise zusammen und stellten fest: [Es waren] 50.000 Silbermünzen.',
        20: 'So gewann das Wort des Herrn weiter an Einfluss, und es war mächtig.',
        21: 'Als nun diese [Dinge] erfüllt waren, nahm sich Paulus im Geist vor, Makedonia und Achaja zu durchqueren und nach Jerusalem zu gehen, und sagte: „Nachdem ich dort gewesen bin, muss ich auch Rom sehen.“',
        22: 'Da sandte er zwei von denen, die ihm dienten, Timotheus und Erastus, nach Makedonia; er selbst blieb [noch] eine Weile in Asia.',
        23: 'Es entstand aber zu jener Zeit ein nicht geringer Aufruhr über den „Weg“.',
        24: 'Denn jemand namens Demetrius, ein Silberschmied, der silberne Tempel der Artemis anfertigte, brachte den Handwerkern nicht wenig Profit ein.',
        25: 'Nachdem er sie und die Arbeiter, ‹die sich mit solchen Dingen beschäftigten›, versammelt hatte, sagte er: „Männer, ihr wisst, dass aus dieser Arbeit unser Wohlstand stammt,',
        26: 'und ihr seht und hört, dass dieser Paulus nicht nur in Ephesus, sondern fast in ganz Asia eine große Gruppe überzeugt und verdreht hat, indem er sagt, dass Götter, die durch Hände entstehen, keine seien.',
        27: 'Es besteht aber nicht nur für uns Gefahr, dass dieses Gewerbe in Verruf gerät, sondern auch, dass der Tempel der großen Göttin Artemis für nichts erachtet wird, und sie sogar ihrer Majestät beraubt zu werden droht, die ganz Asia und der Erdkreis anbetet!“',
        28: 'Und als sie das hörten und voller Wut wurden, schrien sie und sagten: „Groß [ist] die Artemis der Epheser!“',
        29: 'Und die Stadt wurde von Tumult erfüllt, und einmütig drängten sie in das Theater und rissen die Makedonier Gaius und Aristarch mit sich, Paulus’ Reisegefährten.',
        30: 'Als nun Paulus zu der Volksversammlung hineingehen wollte, ließen ihn die Jünger nicht.',
        31: 'Aber auch einige der Asiarchen, die seine Freunde waren, schickten [eine Nachricht] zu ihm und baten ihn, sich nicht in das Theater zu begeben.',
        32: 'Jeder schrie also etwas anderes; die Versammlung war nämlich in ein Chaos gestürzt und die meisten wussten nicht, weswegen sie zusammengekommen waren.',
        33: 'Und [einige] aus der Menschenmenge instruierten Alexander, als die Judäer ihn vorschoben; Alexander wiederum winkte mit der Hand und wollte sich vor dem Volk verteidigen.',
        34: 'Als sie aber erkannten, dass er ein Judäer war, entstand eine einzige Stimme aus [dem Mund] aller, die für etwa zwei Stunden schrien: „Groß [ist] die Artemis der Epheser!“',
        35: 'Da besänftigte der Schreiber die Menschenmenge und sagt: „Männer, Epheser, wer ist denn unter den Menschen, der nicht weiß, dass die Stadt der Epheser ein Tempelhüter der großen Artemis und des vom Himmel gefallenen [Standbildes] ist?',
        36: 'Weil das also unbestritten ist, ist es notwendig, dass ihr besänftigt seid und nichts Voreiliges tut.',
        37: 'Denn ihr habt diese Männer gebracht, die weder Tempelräuber [sind] noch über unsere Göttin gelästert haben.',
        38: 'Wenn also Demetrius und die Handwerker mit ihm eine Sache gegen jemanden haben, dann werden Gerichtstage gehalten, und es sind Statthalter da – sie sollen einander verklagen!',
        39: 'Aber wenn ihr irgendetwas darüber hinaus sucht, dann wird es in der rechtmäßigen Versammlung verhandelt werden.',
        40: 'Denn wir laufen sogar Gefahr, wegen des heutigen [Tages] einer Rebellion angeklagt zu werden, da es keinen Grund gibt, womit wir eine Erklärung für diese Zusammenkunft geben könnten.“Und nachdem er dies gesagt hatte, löste er die Versammlung auf.',
    },
    20: {
        1: 'Nachdem nun der Tumult aufgehört hatte, bestellte Paulus die Jünger zu sich und ermutigte sie; [anschließend] verabschiedete er sich und brach auf, um nach Makedonia zu reisen.',
        2: 'Und nachdem er jene Teile [des Landes] durchquert und sie mit einer langen Rede ermutigt hatte, ging er nach Griechenland',
        3: 'und verbrachte [dort] drei Monate. Da von den Judäern ein Anschlag gegen ihn unternommen wurde, als er im Begriff stand, nach Syria aufzubrechen, ‹fasste er den Entschluss›, durch Makedonia zurückzukehren.',
        4: 'Und es begleiteten ihn Sopater, [Sohn] des Pyrrhus, aus Beröa, und von den Thessalonichern Aristarchus und Sekundus, und Gaius aus Derbe, und Timotheus, und aus Asia Tychikus und Trophimus.',
        5: 'Und diese gingen voraus und warteten in Troas auf uns,',
        6: 'wir hingegen segelten nach den Tagen der ungesäuerten [Brote] von Philippi ab und kamen innerhalb von fünf Tagen zu ihnen nach Troas, wo wir sieben Tage blieben.',
        7: 'Am ersten Tag der Woche nun, als wir uns versammelten hatten, um Brot zu brechen, debattierte Paulus mit ihnen, obwohl er am folgenden [Tag] abzureisen gedachte, und er weitete [seine] Rede bis Mitternacht aus.',
        8: 'Es waren aber etliche Lampen in dem oberen Zimmer, wo wir versammelt waren.',
        9: 'Und ein gewisser junger Mann namens Eutychus saß auf der Fensterbank und wurde durch einen tiefen Schlaf überwältigt, während Paulus noch immer debattierte; vom Schlaf überwältigt, fiel er vom dritten Stock hinunter und wurde tot aufgehoben.',
        10: 'Da stieg Paulus hinab und warf sich auf ihn, und als er ihn umschlang, sagte er: „Seid nicht beunruhigt, denn seine Seele ist in ihm!“',
        11: 'Und nachdem er [wieder] hinaufgestiegen war und das Brot gebrochen und genossen hatte, redete er auch noch weiter, bis Sonnenaufgang, und reiste anschließend ab.',
        12: 'Sie brachten aber den Jungen lebendig [nach Hause], und sie wurden nicht [nur] mittelmäßig ermutigt.',
        13: 'Wir aber gingen voraus zum Boot und brachen nach Assos auf, wo wir Paulus aufzunehmen gedachten; denn so hatte er es angeordnet, da er selbst zu Fuß zu gehen wollte.',
        14: 'Als er nun in Assos zu uns stieß, nahmen wir ihn auf und kamen nach Mitylene.',
        15: 'Und von dort segelten wir am folgenden [Tag] ab und trafen gegenüber von Chios ein, und am anderen [Tag] erreichten wir Samos und am übernächsten [Tag] kamen wir nach Milet.',
        16: 'Paulus hatte nämlich entschieden, an Ephesus vorbeizusegeln, damit es ihm nicht passiert, Zeit in Asia zu verlieren; denn er beeilte sich, um – wenn es ihm möglich wäre – den Pfingsttag in Jerusalem zu verbringen.',
        17: 'Von Milet aber schickte er [eine Nachricht] nach Ephesus und rief die Ältesten der Gemeinde herüber.',
        18: 'Als sie nun bei ihm ankamen, sagte er zu ihnen: „Ihr wisst, wie ich seit dem ersten Tag, an dem nach Asia kam, die ganze Zeit bei euch gewesen bin,',
        19: 'wobei ich dem Herrn mit aller Demut und Tränen und Anfechtungen diente, die mir durch die Anschläge der Judäer widerfuhren;',
        20: 'wie ich nichts zurückgehalten habe, was nützlich ist, um es euch zu verkünden und euch zu lehren, öffentlich und von Haus zu Haus,',
        21: 'indem ich sowohl Judäern als auch Griechen die Umkehr zu Gott und den Glauben an unserem Herrn Jesus bezeugte.',
        22: 'Und jetzt, siehe!, gebunden durch den Geist, gehe ich nach Jerusalem, obwohl ich nicht weiß, was mir dort zustoßen wird,',
        23: 'außer dass mir der heilige Geist von Stadt zu Stadt bezeugt und sagt, dass mich Fesseln und Bedrängnisse erwarten.',
        24: 'Doch für mich selbst erachte ich [mein] Leben keiner Rede wert, um meine Aufgabe und meinen Dienst zu beenden, den ich vom Herrn Jesus erhalten habe: die gute Nachricht von der Gnade Gottes zu bezeugen.',
        25: 'Und jetzt, siehe!, weiß ich, dass ihr alle, unter denen ich umherging und das Königreich predigte, mein Angesicht nicht mehr sehen werdet.',
        26: 'Deshalb bezeuge ich euch am heutigen Tag, dass ich rein bin vom Blut aller [Menschen];',
        27: 'denn ich habe nicht zurückgehalten, euch den ganzen Willen Gottes zu verkünden.',
        28: 'Achtet auf euch selbst und auf die ganze Herde, in die euch der heilige Geist als Aufseher gestellt hat [mit dem Auftrag], die Gemeinde Gottes zu weiden, die er durch sein eigenes Blut erworben hat.',
        29: 'Ich weiß, dass nach meinem Abschied gefährliche Wölfe zu euch hereinkommen werden, die die Herde nicht verschonen.',
        30: 'Und von euch selbst werden Männer aufstehen, die verkehrte [Dinge] reden, um die Jünger hinter sich zu bringen.',
        31: 'Darum seid wachsam und erinnert euch, dass ich drei Jahre lang Nacht und Tag nicht aufgehört habe, jeden Einzelnen unter Tränen zu warnen.',
        32: 'Und jetzt vertraue ich euch Gott und dem Wort seiner Gnade an, das imstande ist, aufzuerbauen und das Erbe zu geben unter all denen, die geheiligt sind.',
        33: 'Ich habe von niemandem Silber oder Gold oder Kleidung verlangt.',
        34: 'Ihr selbst wisst, dass diese Hände meinen Bedürfnissen und denen, die bei mir sind, gedient haben.',
        35: 'Ich habe euch alles gezeigt: dass man sich in dieser Weise bemühen und sich der Schwachen annehmen und an die Worte des Herrn Jesus erinnern muss, weil er selbst gesagt hat: ‚Beglückwünschenswert ist es, eher zu geben als zu nehmen.‘“',
        36: 'Und nachdem er diese [Dinge] gesagt hatte, ging er auf seine Knie und betete mit ihnen allen.',
        37: 'Und bei allen entstand eine große Traurigkeit, und sie fielen Paulus um den Hals und küssten ihn innig,',
        38: 'da sie besonders über das Wort betrübt waren, das er gesagt hatte, dass sie sein Angesicht nicht mehr sehen würden. Dann geleiteten sie ihn zum Schiff.',
    },
    21: {
        1: 'Als es aber geschah, dass wir aufbrachen und uns von ihnen verabschiedeten, da nahmen wir direkten Kurs und kamen nach Kos, am nächsten [Tag] wiederum nach Rhodos, und von dort nach Patara,',
        2: 'und als wir ein Schiff fanden, das nach Phönizien übersetzte, bestiegen wir es und brachen auf.',
        3: 'Und nachdem wir Zypern gesichtet und es links liegen gelassen hatten, segelten wir nach Syria und legten in Tyrus an; dort hatte das Schiff nämlich die Ladung abzuliefern.',
        4: 'Und nachdem wir die Jünger gefunden hatten, blieben wir sieben Tage dort; sie sagten zu Paulus durch den Geist, nicht nach Jerusalem hinaufzusteigen.',
        5: 'Als es aber geschah, dass wir die Tage verbracht hatten, da reisten wir ab und gingen los, wobei uns alle samt Frauen und Kindern bis draußen vor die Stadt geleiteten, und wir gingen am Strand auf die Knie, beteten,',
        6: 'verabschiedeten einander, und dann stiegen wir in das Schiff, sie aber kehrten nach Hause zurück.',
        7: 'Wir aber, als wir die Fahrt beendet hatten, gelangten von Tyrus nach Ptolemaïs und begrüßten die Geschwister und blieben einen Tag bei ihnen.',
        8: 'Und am folgenden [Tag] reisten wir ab und kamen nach Cäsarea, und wir gingen in das Haus des Evangelisten Philippus, der [einer] von den sieben [Diakonen] war, und blieben bei ihm.',
        9: 'Der wiederum hatte vier Töchter, Jungfrauen, die weissagten.',
        10: 'Während wir nun mehrere Tage blieben, kam jemand von Judäa herab, ein Prophet namens Agabus,',
        11: 'und er kam zu uns und nahm den Gürtel von Paulus, fesselte seine Füße und Hände und sagte: „Folgendes sagt der heilige Geist: ‚Den Mann, dem dieser Gürtel gehört, werden die Judäer in Jerusalem auf dieselbe Weise fesseln und an die Hände der [heidnischen] Völker ausliefern.‘“',
        12: 'Als wir nun diese [Dinge] hörten, baten wir und die Einheimischen ihn, nicht nach Jerusalem hinaufzusteigen.',
        13: 'Daraufhin antwortete Paulus: „Was tut ihr, dass ihr weint und mir das Herz brecht? Denn ich bin bereit, nicht nur gefesselt zu werden, sondern auch in Jerusalem für den Namen des Herrn Jesus zu sterben.“',
        14: 'Da er sich aber nicht überreden ließ, schwiegen wir und sagten: „Des Herrn Wille soll geschehen!“',
        15: 'Nach diesen Tagen nun machten wir uns fertig und stiegen hinauf nach Jerusalem.',
        16: 'Es gingen aber auch [einige] von den Jüngern aus Cäsarea mit uns, um uns zu einem gewissen Mnason aus Zypern zu bringen, einem Jünger aus den Anfängen, bei dem wir beherbergt wurden.',
        17: 'Und als wir nach Jerusalem kamen, empfingen uns die Geschwister freundlich.',
        18: 'Am folgenden [Tag] aber ging Paulus mit uns zu Jakobus, und alle Ältesten fanden sich ein.',
        19: 'Und nachdem er sie begrüßt hatte, führte er eines nach dem anderen aus, was Gott unter den [heidnischen] Völkern durch seinen Dienst getan hatte.',
        20: 'Sie wiederum verherrlichten Gott, als sie es hörten, und sie sagten zu ihm: „Du siehst, Bruder, wie viele Tausende von Gläubigen es unter den Judäern gibt, und sie alle sind Verfechter des Gesetzes.',
        21: 'Sie wurden aber über dich unterrichtet, dass du allen Judäern, die unter den [heidnischen] Völkern [leben], Abtrünnigkeit von Mose lehrst, indem du sagst, dass sie die Kinder nicht zu beschneiden noch entsprechend den Bräuchen zu leben hätten.',
        22: 'Was also ist [zu tun]? Zweifellos werden sie hören, dass du gekommen bist.',
        23: 'Tu also das, was wir dir sagen: Wir haben vier Männer, die einen Schwur auf sich selbst geleistet haben.',
        24: 'Nimm dich ihrer an und lass dich zusammen mit ihnen reinigen, und ‹komm für ihre Unkosten auf›, damit sie sich den Kopf rasieren können, dann werden alle erkennen, dass das, was man über dich erzählt, nichts bedeutet, sondern auch du selbst dich danach richtest, das Gesetz zu wahren.',
        25: 'Aber bezüglich der Heiden, die zum Glauben gekommen sind, haben wir [eine Nachricht] gesandt, nachdem wir entschieden hatten, dass sie Götzen Geopfertes und Blut und Ersticktes und Unmoral meiden sollten.“',
        26: 'Daraufhin nahm sich Paulus der Männer an, ließ sich am nächsten Tag zusammen mit ihnen reinigen und ging in den Tempel, um die Erfüllung der Tage der Reinigung bekannt zu geben, bis für jeden Einzelnen von ihnen das Opfer dargebracht worden war.',
        27: 'Als nun die sieben Tage beinahe vollendet waren, sahen ihn die Judäer aus Asia im Tempel und wiegelten die ganze Menschenmenge auf, und sie legten die Hände an ihn',
        28: 'und schrien: „Männer von Israel, helft [uns]! Dies ist der Mann, der alle [Menschen] überall gegen das Volk und das Gesetz und diese Stätte lehrt, und er hat auch noch Griechen in den Tempel gebracht und diese heilige Stätte entweiht!“',
        29: '(Denn sie hatten zuvor Trophimus, den Epheser, mit ihm in der Stadt gesehen, von dem sie meinten, dass Paulus ihn in den Tempel gebracht hätte.)',
        30: 'Und die gesamte Stadt geriet in Bewegung, und es entstand ein Auflauf des Volkes, und sie ergriffen Paulus und schleiften ihn aus dem Tempel, und gleich darauf wurden die Türen geschlossen.',
        31: 'Und während sie versuchten, ihn zu töten, ging ein Bericht hinauf zu dem Kommandanten der Kohorte, dass ganz Jerusalem in Aufruhr gerate.',
        32: 'Der nahm sofort [einige] Soldaten und Zenturionen und lief zu ihnen hinunter, sie aber hörten auf, Paulus zu schlagen, als sie den Kommandanten und die Soldaten sahen.',
        33: 'Daraufhin näherte sich der Kommandant und ergriff ihn, dann befahl er, ihn mit zwei Ketten zu fesseln, und er erkundigte sich, wer er sei und was er getan habe.',
        34: 'Aber jeder rief etwas anderes in der Menschenmenge. Da er nun nicht imstande war, Details über den Tumult zu erfahren, befahl er, ihn in die Kaserne zu führen.',
        35: 'Als er aber zu den Stufen kam, passierte es, dass er wegen der Gewalt der Menschenmenge von den Soldaten getragen wurde,',
        36: 'denn die Menge des Volkes folgte und schrie: „Weg mit ihm!“',
        37: 'Und als er gerade in die Kaserne geführt werden sollte, sagt Paulus zu dem Kommandanten: „Ist es mir erlaubt, etwas zu dir zu sagen?“Er aber sagte: „Verstehst du Griechisch?',
        38: 'Du bist also nicht der Ägypter, der vor diesen Tagen Unruhe gestiftet hat und die 4.000 Männer von den Sikariern in die Wüste hinausgeführt hat?“',
        39: 'Da sagte Paulus: „Ich bin ein judäischer Mann, aus Tarsus in Kilikia, Bürger einer nicht unberühmten Stadt. Nun bitte ich dich: Gestatte mir, zu dem Volk zu reden.“',
        40: 'Und da er es gestattete, winkte Paulus dem Volk mit der Hand, während er auf den Stufen stand. Als nun eine große Stille entstand, redete er sie in hebräischer Sprache an und sagte:',
    },
    22: {
        1: '„Männer, Brüder und Väter, hört jetzt auf meine Verteidigung euch gegenüber!“',
        2: 'Als sie nun hörten, dass er sie in hebräischer Sprache anredete, hielten sie erst recht Stille. Dann sagt er:',
        3: '„Ich bin ein judäischer Mann, geboren in Tarsus in Kilikia, aber aufgewachsen in dieser Stadt, bei den Füßen Gamaliëls, erzogen nach der Strenge des Gesetzes unserer Väter, war ein Eiferer Gottes (wie ihr alle es heute seid),',
        4: 'der ich diesen „Weg“bis zum Äußersten verfolgt habe, indem ich sowohl Männer als auch Frauen gefesselt und an Gefängnisse ausgeliefert habe,',
        5: 'wie mir auch der Oberpriester und der ganze Ältestenrat bestätigt, von denen ich sogar Briefe an die Brüder in Damaskus erhalten habe; [so] ging ich hin, um auch diejenigen, die dort waren, gefesselt nach Jerusalem führen, damit sie bestraft werden.',
        6: 'Es geschah aber, während ich hinging und mich Damaskus näherte, dass um die Mittagszeit plötzlich aus dem Himmel ein kräftiges Licht um mich herum schien,',
        7: 'und ich fiel zu Boden und hörte eine Stimme, die zu mir sagte: ‚Saul, Saul, warum verfolgst du mich?‘',
        8: 'Ich wiederum antwortete: ‚Wer bist du, Herr?‘Und er sagte zu mir: ‚Ich bin Jesus, der Nazoräer, den du verfolgst.‘',
        9: 'Diejenigen aber, die bei mir waren, sahen zwar das Licht, aber die Stimme dessen, der zu mir redete, hörten sie nicht.',
        10: 'Da sagte ich: ‚Was soll ich tun, Herr?‘Der Herr aber sagte zu mir: ‚Steh auf und geh nach Damaskus, und dort wird dir alles gesagt werden, was dir zu tun verordnet ist.‘',
        11: 'Als ich nun wegen der Helligkeit jenes Lichts nicht sehen [konnte], wurde ich von ‹meinen Begleitern› an der Hand geführt und kam [so] nach Damaskus.',
        12: 'Ein gewisser Hananias aber, ein frommer Mann nach dem Gesetz, der von allen Judäern, die [dort] wohnten, mit einem guten Leumund versehen wurde,',
        13: 'kam zu mir und trat heran und sagte zu mir: ‚Saul, Bruder, du sollst wieder sehen!‘Und ich schaute in diesem Moment zu ihm auf.',
        14: 'Er aber sagte: ‚Der Gott unserer Vorfahren hat dich dazu bestimmt, seinen Willen zu erkennen und den Gerechten zu sehen und eine Stimme aus seinem Mund zu hören,',
        15: 'weil du zu allen Menschen für ihn ein Zeuge dessen sein wirst, was du gesehen und gehört hast.',
        16: 'Und warum zögerst du jetzt? Steh auf, lass dich taufen und lass dir deine Sünden abwaschen, indem du seinen Namen anrufst!‘',
        17: 'Es geschah aber, als ich nach Jerusalem zurückgekehrt war und im Tempel betete, dass ich in eine Trance geriet',
        18: 'und ihn sah, der zu mir sagte: ‚Beeile dich und geh schnell aus Jerusalem weg, weil sie dein Zeugnis über mich nicht annehmen werden.‘',
        19: 'Und ich sagte: ‚Herr, sie selbst wissen, dass ich es war, der von Synagoge zu Synagoge diejenigen festnahm und schlug, die an dich glaubten,',
        20: 'und als das Blut deines Zeugen Stephanus vergossen wurde, war es auch ich selbst, der dabeistand und seine Zustimmung gab und die Gewänder derer bewachte, die ihn umbrachten.‘',
        21: 'Und dann er sagte zu mir: ‚Geh, denn ich werde dich zu [heidnischen] Völkern weit hinaussenden.‘“',
        22: 'Sie hörten ihm aber bis zu diesem Wort zu, und sie erhoben ihre Stimme und sagten: „Weg von der Erde mit dem da, denn es darf nicht sein, dass er am Leben bleibt!“',
        23: 'Und während sie schrien und die Gewänder wegschleuderten und Staub in die Luft warfen,',
        24: 'befahl der Kommandant, ihn in die Kaserne zu bringen, und sagte, dass er mit Geißelhieben zu untersuchen wäre, damit er erfährt, aus welchem Grund sie dermaßen gegen ihn schrien.',
        25: 'Als sie ihn aber für die Riemen ausgestreckt hatten, sagte Paulus zu dem Zenturio, der dabeistand: „Ist es euch erlaubt, einen römischen und unverurteilten Menschen zu geißeln?“',
        26: 'Als nun der Zenturio das hörte, ging er zu dem Kommandanten und machte Meldung und sagte: „Was gedenkst du zu tun? Schließlich ist dieser Mensch ein Römer.“',
        27: 'Da kam der Kommandant dazu und sagte zu ihm: „Sag mir: Bist du ein Römer?“Er aber sagte: „Ja.“',
        28: 'Da antwortete der Kommandant: „Ich habe mir dieses Bürgerrecht für eine große Summe erworben.“Paulus aber sagte: „Ich hingegen bin sogar [als Römer] geboren.“',
        29: 'Sofort ließen also diejenigen von ihm ab, die ihn untersuchen sollten, aber auch der Kommandant fürchtete sich, als er erfuhr, dass er ein Römer war, und zwar weil er ihn gefesselt hatte.',
        30: 'Am folgenden [Tag] aber, da er Details erfahren wollte, warum er von den Judäern angeklagt wurde, machte er ihn los, und er befahl, dass die Oberpriester und das ganze Synedrium zusammenkämen, und er brachte Paulus hinab und stellte ihn zu ihnen.',
    },
    23: {
        1: 'Da richtete Paulus den Blick auf das Synedrium und sagte: „Männer, Brüder, ich habe bis zu diesem Tag mit einem völlig guten Gewissen für Gott gelebt.“',
        2: 'Der Oberpriester Hananias aber befahl, denen die dabeistanden, ihm auf seinen Mund zu schlagen.',
        3: 'Daraufhin sagte Paulus zu ihm: „Gott wird dich schlagen, du getünchte Wand! Und du sitzt da und richtest mich nach dem Gesetz, derweil missachtest du das Gesetz und befiehlst, dass ich geschlagen werde?!?“',
        4: 'Aber die dabeistanden sagten: „Den Oberpriester Gottes beleidigst du?“',
        5: 'Da sagte Paulus: „Ich wusste nicht, Brüder, dass er Oberpriester ist! Schließlich steht geschrieben: ‚Über einen Oberen deines Volkes sollst du nicht schlecht reden!‘',
        6: 'Als Paulus nun bemerkte, dass der eine Teil von den Sadduzäern war und der andere von den Pharisäern, rief er im Synedrium: „Männer, Brüder, ich bin ein Pharisäer, ein Sohn von Pharisäern! Bezüglich der Hoffnung und der Auferstehung der Toten werde ich gerichtet.“',
        7: 'Und als er das sagte, entstand eine Aufruhr der Pharisäer und Sadduzäer, und die Menge wurde gespalten.',
        8: 'Denn die Sadduzäer sagen, dass es weder eine Auferstehung noch Engel noch Geist gäbe, die Pharisäer hingegen bekennen beides.',
        9: 'Da entstand ein großes Geschrei, und einige der Schriftgelehrten des Teils der Pharisäer standen auf, protestierten und sagten: „Wir finden nichts Schlechtes an diesem Menschen; aber wenn ein Geist oder ein Engel zu ihm geredet hat …“',
        10: 'Als nun eine große Aufruhr entstand, fürchtete der Kommandant, Paulus würde von ihnen zerrissen werden, und er befahl, dass die Armee hinuntergehen, ihn aus ihrer Mitte reißen und in die Kaserne bringen solle.',
        11: 'Aber in der folgenden Nacht stand der Herr bei ihm und sagte: „Sei guten Mutes! Denn wie du über mich in Jerusalem Zeugnis abgelegt hast, so musst du auch in Rom Zeugnis ablegen.“',
        12: 'Als es nun Tag wurde, planten die Judäer eine Verschwörung und schworen sich, indem sie sagten, weder zu essen noch zu trinken, bis sie Paulus getötet hätten.',
        13: 'Es waren aber mehr als vierzig, die dieses Komplott planten;',
        14: 'sie gingen zu den Oberpriestern und den Ältesten und sagten: „Wir haben uns feierlich geschworen, nichts zu genießen, bis wir Paulus getötet haben.',
        15: 'Also sollt ihr jetzt dem Kommandanten samt dem Synedrium verdeutlichen, dass er ihn zu euch hinunterbringen soll, als ob ihr vorhättet, ‹seinen Fall› genauer zu untersuchen. Wir aber sind bereit, ihn umzubringen, bevor er sich nähert.“',
        16: 'Als nun der Sohn von Paulus’ Schwester von dem Anschlag hörte, kam er und ging in die Kaserne, um es Paulus zu berichten.',
        17: 'Da rief Paulus einen der Zenturionen zu sich und sagte: „Bring diesen jungen Mann zum Kommandanten, denn er hat ihm etwas zu berichten.“',
        18: 'Der nahm sich also seiner an und führte ihn zu dem Kommandanten, und er sagt: „Der Gefangene Paulus hat mich zu sich gerufen und mich gebeten, diesen jungen Mann zu dir zu bringen, der dir etwas zu sagen hat.“',
        19: 'Da ergriff der Kommandant seine Hand und zog sich [mit ihm] privat zurück und erkundigte sich: „Was ist es, das du mir zu berichten hast?“',
        20: 'Da sagte er: „Die Judäer haben verabredet, dich zu bitten, dass du Paulus morgen in das Synedrium hinabführst, als ob es vorhätte, sich etwas genauer über ihn zu erkundigen.',
        21: 'Lass du dich also nicht von ihnen überreden! Denn mehr als vierzig Männer von ihnen, die sich geschworen haben, weder zu essen noch zu trinken, bis sie ihn umgebracht haben, lauern auf ihn, und jetzt sind sie bereit und erwarten die Ankündigung von dir.“',
        22: 'Der Kommandant ließ also den jungen Mann [gehen] und befahl ihm, niemandem zu erzählen, „dass du diese [Dinge] mir gegenüber vorgebracht hast.“',
        23: 'Dann rief er zwei der Zenturionen zu sich und sagte: „Macht zweihundert Soldaten bereit, damit sie bis nach Cäsarea ziehen, außerdem siebzig Reiter und zweihundert Speerwerfer, ab der dritten Stunde der Nacht,',
        24: 'und stellt Lasttiere bereit, um Paulus daraufsetzen und sicher zu Felix dem Statthalter zu bringen!“',
        25: 'Er schrieb einen Brief, der folgenden Inhalt hatte:',
        26: '„Claudius Lysias, an den ehrenwerten Statthalter Felix. Sei gegrüßt!',
        27: 'Diesen Mann, der von den Judäern verhaftet worden war und von ihnen umgebracht werden sollte, habe ich gerettet, indem ich mit der Armee einschritt, als ich erfuhr, dass er Römer sei.',
        28: 'Und da ich den Grund erfahren wollte, weswegen sie ihn anklagten, führte ich ihn zu ihrem Synedrium hinab.',
        29: 'Ich befand, dass er für Streitfragen ihres Gesetzes angeklagt wurde, aber keine Anklage vorlag, die des Todes oder einer Gefangenschaft würdig [gewesen wäre].',
        30: 'Da mir aber zu Ohren kam, dass ein Anschlag gegen den Mann geschehen würde, habe ich ihn sofort zu dir geschickt und auch den Kläger befohlen, vor dir auszusagen, was gegen ihn [vorliegt].“',
        31: 'Gemäß dem, was ihnen aufgetragen worden war, nahmen also die Soldaten Paulus und brachten ihn während der Nacht nach Antipatris,',
        32: 'und am folgenden [Tag] ließen sie die Reiter zusammen mit ihm aufbrechen und kehrten in die Kaserne zurück.',
        33: 'Als sie nach Cäsarea kamen und dem Statthalter den Brief überreichten, präsentierten sie ihm auch Paulus.',
        34: 'Und nachdem er [den Brief] gelesen und gefragt hatte, aus welcher Provinz er sei, und erfahren hatte, dass [er] aus Kilikia [stamme],',
        35: 'sagte er: „Ich werde dich anhören, sobald auch deine Ankläger angekommen sind“, und befahl, ihn im Prätorium von Herodes zu bewachen.',
    },
    24: {
        1: 'Fünf Tage später stieg nun der Oberpriester Hananias mit einigen Ältesten und einem Redner, einem gewissen Tertullus, herab, welche dem Statthalter [ihre Vorwürfe] gegen Paulus vortrugen.',
        2: 'Als er nun aufgerufen wurde, begann Tertullus mit der Anklage und sagte: „Dass wir großen Frieden durch dich erfahren und diesem Volk durch deine Fürsorge Reformen zukommen,',
        3: 'erkennen wir in allem und überall an, edelster Felix, mit aller Dankbarkeit.',
        4: 'Damit ich dich aber nicht allzu sehr bemühe, bitte ich dich, uns in deiner Großzügigkeit kurz anzuhören.',
        5: 'Wir haben nämlich festgestellt, dass dieser Mann eine Pest [ist] und Unruhen stiftet unter allen Judäern, die auf dem Erdkreis [sind], und ein Anführer der Partei der Nazoräer [ist],',
        6: 'der sogar den Tempel zu entweihen versuchte [und] den wir [deshalb] auch verhaftet haben.',
        8: 'Von ihm wirst du – wenn du ihn selbst untersucht hast – alles über die [Dinge] erfahren können, derer wir ihn anklagen.“',
        9: 'Da stimmten auch die Judäer ein und bestätigten, dass sich dies so verhielte.',
        10: 'Paulus antwortete aber, als ihm der Statthalter Zeichen gab zu reden: „Da ich weiß, dass du seit vielen Jahren Richter für dieses Volk bist, verteidige ich ‹meine Sache› zuversichtlich,',
        11: 'indem du erfahren kannst, dass es nicht mehr als zwölf Tage sind, seitdem ich hinaufgestiegen bin, um in Jerusalem anzubeten.',
        12: 'Und sie haben mich weder im Tempel noch in den Synagogen noch in der Stadt mit jemand diskutieren oder einen Auflauf der Menschenmenge provozieren gesehen.',
        13: 'Noch können sie dir beweisen, wofür sie jetzt mich anklagen.',
        14: 'Ich bekenne dir aber Folgendes: Gemäß dem „Weg“, den sie eine Sekte nennen, so diene ich dem Gott unserer Väter, da ich allem glaube, das gemäß dem Gesetz [ist] und das in den Propheten geschrieben steht,',
        15: 'und habe [dieselbe] Hoffnung in Gott, die auch sie selbst erwarten: dass es eine Auferstehung geben wird, sowohl der Gerechten als auch der Ungerechten.',
        16: 'Darum bin auch ich selbst bestrebt, stets ein einwandfreies Gewissen gegenüber Gott und den Menschen zu haben.',
        17: 'Nach mehreren Jahren nun kam ich, um Almosen an mein Volk und Opfer darzubringen,',
        18: 'bei denen sie mich gereinigt im Tempel fanden, nicht mit einer Menschenmenge und nicht mit einem Tumult;',
        19: 'und [trotzdem bezichtigen mich] einige Judäer aus Asia, die vor dir anwesend sein und Anklage erheben müssten, wenn sie etwas gegen mich hätten.',
        20: 'Oder sie selbst sollten sagen, welches Verbrechen sie festgestellt haben, als ich vor dem Synedrium stand,',
        21: 'außer über diese eine Aussage, die ich ausrief, als ich unter ihnen stand: ‚Bezüglich der Auferstehung der Toten werde ich heute vor euch gerichtet!‘“',
        22: 'Da wies Felix sie zurück, weil er über den „Weg“genauer Bescheid wusste, und sagte: „Sobald der Kommandant Lysius herabkommt, werde ich ‹euer Anliegen› entscheiden.“',
        23: 'Er ordnete dem Zenturio an, dass er bewacht werde und Freigang habe und keinen seiner Leute daran zu hindern, ihm zu dienen.',
        24: 'Einige Tage später nun kam Felix zusammen mit seiner Ehefrau Drusilla, die Judäerin war, und bestellte Paulus, und er hörte ihn an über den Glauben an Christus Jesus.',
        25: 'Und während er über Gerechtigkeit und Selbstbeherrschung und das bevorstehende Gericht diskutierte, wurde Felix ängstlich und antwortete: „Für jetzt geh hin, aber sobald ich Zeit habe, werde ich dich herbitten.“',
        26: 'Zugleich hoffte er auch, dass ihm von Paulus Schmiergeld gegeben würde; deshalb bestellte er ihn noch häufiger und unterhielt sich mit ihm.',
        27: 'Als aber zwei Jahre vergangen waren, bekam Felix den Porcius Festus als Nachfolger, und da sich Felix bei den Judäern in Gunst setzen wollte, hinterließ er Paulus als Gefangenen.',
    },
    25: {
        1: 'Festus betrat also die Provinz und stieg nach drei Tagen von Cäsarea hinauf nach Jerusalem,',
        2: 'und die Oberpriester und die wichtigsten der Judäer trugen ihm [ihre Vorwürfe] gegen Paulus vor, und sie forderten ihn auf',
        3: '(wobei sie einen Gefallen gegen ihn erbaten), dass er ihn nach Jerusalem bestellen solle, wobei sie einen Anschlag verüben würden, um ihn entlang des Weges umzubringen.',
        4: 'Festus antwortete also, dass Paulus in Cäsarea verwahrt werde, er selbst aber in Kürze aufbrechen wolle.',
        5: '„Die Sachverständigen unter euch“, sagt er, „sollen also mit hinabsteigen und ihn anklagen, wenn irgendetwas Unvorbildliches an dem Mann ist.“',
        6: 'Nachdem er sich aber nicht mehr als acht oder zehn Tage unter ihnen aufgehalten hatte, stieg er nach Cäsarea hinab; am folgenden [Tag] setzte er sich auf den Richterstuhl und befahl, Paulus vorzuführen.',
        7: 'Als er nun ankam, umringten ihn die Judäer, die von Jerusalem herabgestiegen waren, und brachten viele und schwere Anschuldigungen vor, die sie nicht beweisen konnten,',
        8: 'während sich Paulus verteidigte: „Weder gegen das Gesetz der Judäer noch gegen den Tempel noch gegen Cäsar habe ich in irgendeiner Weise gesündigt.“',
        9: 'Da Festus aber den Judäern einen Gefallen tun wollte, antwortete er Paulus und sagte: „Willst du nach Jerusalem hinaufsteigen und dort hinsichtlich dieser [Vorwürfe] vor mir gerichtet werden?“',
        10: 'Da sagte Paulus: „Ich stehe vor dem Richterstuhl Cäsars, wo ich gerichtet werden muss. Den Judäern habe ich kein Unrecht getan, wie auch du sehr wohl weißt.',
        11: 'Wenn ich also Unrecht tue und irgendetwas getan habe, das des Todes würdig [ist], dann weigere ich mich nicht zu sterben. Aber wenn nichts von dem [wahr] ist, dessen diese [Leute] mich anklagen, dann kann niemand mich ihnen preisgeben. Ich berufe mich auf Cäsar!“',
        12: 'Daraufhin besprach sich Festus mit dem Rat und antwortete: „Auf Cäsar hast du dich berufen, zum Cäsar sollst du gehen!“',
        13: 'Als nun einige Tage vergangen waren, trafen Agrippa der König und Bernike nach Cäsarea ein, um Festus zu begrüßen.',
        14: 'Und während sie sich dort mehrere Tage aufhielten, legte Festus dem König die [Anschuldigungen] gegen Paulus vor und sagte: „Ein gewisser Mann ist von Felix als Gefangener zurückgelassen worden,',
        15: 'über den die Oberpriester und die Ältesten der Judäer [ihre Anschuldigungen] vorgetragen haben, als ich in Jerusalem war, und mich um eine Verurteilung gegen ihn gebeten haben.',
        16: 'Ihnen antwortete ich, dass es bei [uns] Römern nicht Sitte sei, einen Menschen preiszugeben, bevor der Angeklagte die Kläger von Angesicht zu Angesicht getroffen und eine Gelegenheit zur Verteidigung hinsichtlich der Anklage erhalten hat.',
        17: 'Als sie nun hierher zusammenkamen, machte ich keine Umschweife, setzte mich am nächsten [Tag] auf den Richterstuhl und befahl, den Mann vorzuführen.',
        18: 'Über den brachten die Ankläger, als sie sich hinstellten, keine einzige Anschuldigung böser [Taten] vor, die ich vermutete;',
        19: 'einige strittige Fragen aber hinsichtlich ihrer eigenen Religiosität hatten sie gegen ihn, und hinsichtlich eines gewissen verstorbenen Jesus, von dem Paulus sagte, er lebe.',
        20: 'Da ich nun in der Untersuchung darüber ratlos war, fragte ich, ob er nach Jerusalem gehen und dort darüber gerichtet werden wolle.',
        21: 'Da sich Paulus aber darauf berufen hatte, bis zur Entscheidung Seiner Majestät bewacht zu werden, befahl ich, dass er bewacht wird, bis ich ihn zu Cäsar schicke.“',
        22: 'Agrippa aber [sagte] zu Festus: „Ich will den Mann auch selbst hören.“„Morgen“, sagt er, „sollst du ihn hören.“',
        23: 'Als nun Agrippa und Bernike am folgenden [Tag] mit einem großen Gefolge kamen und den Versammlungsraum betraten, zusammen mit den Kommandanten und den prominentesten Männern der Stadt, und Festus den Befehl erteilte, wurde Paulus vorgeführt.',
        24: 'Und Festus sagt: „König Agrippa und alle mit uns anwesenden Männer, ihr seht diesen [Mann], über den sich die ganze Menge der Judäer bei mir beschwert hat – sowohl in Jerusalem als auch hier –, indem sie riefen, dass er nicht länger leben dürfe.',
        25: 'Ich aber bin zu dem Schluss gekommen, dass er nichts getan hat, was des Todes würdig [ist]. Da sich aber dieser selbst auf Seine Majestät berufen hat, habe ich beschlossen, [dorthin] zu schicken.',
        26: 'Etwas Genaues über ihn habe ich dem Herrn nicht zu schreiben; darum habe ich ihn euch vorgeführt – und besonders dir, König Agrippa – damit ich etwas zu schreiben habe, wenn die Anhörung abgeschlossen ist.',
        27: 'Denn es scheint mir unsinnig, einen Gefangenen zu schicken und nicht auch die gegen ihn [erhobenen] Vorwürfe anzuzeigen.“',
    },
    26: {
        1: 'Agrippa aber sagte zu Paulus: „Es ist dir gestattet, über dich selbst zu sprechen.“Daraufhin streckte Paulus die Hand aus und verteidigte sich:',
        2: '„Ich schätze mich glücklich, König Agrippa, mich hinsichtlich aller [Dinge], derer ich von den Judäern angeklagt werde, heute vor dir verteidigen zu sollen,',
        3: 'insbesondere da du ein Kenner aller Bräuche und Streitfragen unter den Judäern bist; darum bitte ich [dich], mich geduldig anzuhören.',
        4: 'Also mein Leben seit der Jugend, das von Anfang an in meinem Volk und in Jerusalem stattgefunden hat, kennen alle Judäer,',
        5: 'die mich von früher kennen (wenn sie es bezeugen wollen), [nämlich] dass ich gemäß der strengsten Gruppierung unserer Religion gelebt habe – als ein Pharisäer.',
        6: 'Und jetzt stehe ich [hier] und werde wegen [meiner] Hoffnung auf die von Gott an unsere Vorfahren ergangene Verheißung gerichtet,',
        7: 'zu der hin unser Zwölfstamm zu gelangen hofft, da er mit Ernst [Gott] Nacht und Tag dient. Hinsichtlich dieser Hoffnung werde ich von Judäern angeklagt, oh König!',
        8: 'Warum hält man es bei euch für absurd, dass Gott Tote auferweckt?',
        9: 'Ich meinte also für mich selbst, gegen den Namen von Jesus dem Nazoräer viel Widerstand leisten zu müssen,',
        10: 'was ich in Jerusalem auch getan habe, und zwar habe ich viele der Heiligen in Gefängnissen weggesperrt, nachdem ich die [entsprechende] Vollmacht von den Oberpriestern erhalten hatte, und habe ‹meine Zustimmung gegeben›, wenn sie umgebracht wurden.',
        11: 'Und quer durch alle Synagogen bestrafte ich sie verschiedentlich und zwang sie, [ihren Gott] zu lästern; auch stellte ich ihnen rigoros nach und verfolgte sie sogar bis in die ausländischen Städte.',
        12: 'Unter anderem reiste ich nach Damaskus mit einer Vollmacht und Erlaubnis von den Oberpriestern.',
        13: 'Mitten am Tag entlang des Weges sah ich, oh König, vom Himmel her ein Licht, jenseits der Helligkeit der Sonne, das mich und die mit mir Reisenden umstrahlte.',
        14: 'Und nachdem wir alle zu Boden gefallen waren, hörte ich eine Stimme in hebräischer Sprache zu mir sagen: ‚Saul, Saul, warum verfolgst du mich? [Es wird] schwierig für dich [sein], gegen den Stachel anzutreten.‘',
        15: 'Ich aber sagte: ‚Wer bist du, Herr?‘Der Herr wiederum sagte: ‚Ich bin Jesus, den du verfolgst.',
        16: 'Steh doch auf und stell dich auf deine Füße! Denn dazu bin ich dir erschienen: um dich als Diener und Zeugen einzusetzen, sowohl dessen, worin du mich gesehen hast, als auch dessen, worin ich dir erscheinen werde,',
        17: 'indem ich dich aus dem Volk und aus den [heidnischen] Völkern herausnehme, zu denen ich dich sende,',
        18: 'um ihre Augen zu öffnen, damit sie von Finsternis zum Licht und aus der Gewalt Satans zu Gott umkehren [und] sie Vergebung der Sünden und [ihr] Erbe unter denen erhalten, die durch Glauben an mich geheiligt sind.‘',
        19: 'Von daher, König Agrippa, bin ich der himmlischen Vision nicht ungehorsam geworden,',
        20: 'sondern ich habe zuerst denen in Damaskus und Jerusalem, und dann der ganzen Umgebung Judäas und den [heidnischen] Völkern verkündet, Buße zu tun und zu Gott umzukehren und Werke zu tun, die der Buße würdig [sind].',
        21: 'Deswegen haben mich die Judäer verhaftet, als ich im Tempel war, und es darauf angelegt, mich umzubringen.',
        22: 'Da ich also bis zu diesem Tag Hilfe von Gott erfahren habe, stehe ich [hier], um es Klein und Groß zu bezeugen, obwohl ich nichts sage außer, was auch die Propheten und Mose gesagt haben, das geschehen würde:',
        23: '[nämlich] dass der Gesalbte ein Leidender [sein würde] [und] dass er als der Erste aus der Auferstehung der Toten Licht verkünden würde, sowohl dem Volk als auch den [heidnischen] Völkern.“',
        24: 'Und während er diese [Dinge] als Verteidigung vorbringt, sagt Festus mit lauter Stimme: „Du bist wahnsinnig, Paulus! ‹Das viele Studieren› treibt dich in den Wahnsinn!“',
        25: 'Paulus aber sagt: „Ich bin nicht wahnsinnig, ehrenwerter Festus, sondern ich spreche Worte der Wahrheit und der Besonnenheit.',
        26: 'Denn der König, zu dem ich ja freimütig rede, weiß darüber Bescheid; von daher bin ich nämlich nicht überzeugt, dass ihm irgendetwas davon entgangen ist. Dies ist nämlich nicht in einem [entlegenen] Winkel passiert.',
        27: 'Glaubst du, König Agrippa, den Propheten? Ich weiß, dass du glaubst.“',
        28: 'Agrippa aber [sagte] zu Paulus: „Fast überzeugst du mich, als ein Christ zu handeln.“',
        29: 'Paulus aber [sagte]: „Ich bete zu Gott, dass ‹über kurz oder lang› nicht nur du, sondern auch alle, die mich heute anhören, solche werden, wie auch ich es bin – abgesehen von dieser Gefangenschaft.“',
        30: 'Da standen der König und der Statthalter und Bernike und die bei ihnen saßen auf,',
        31: 'und sie zogen sich zurück und redeten miteinander und sagten: „Dieser Mann tut nichts, was des Todes oder der Gefangenschaft würdig [ist].“',
        32: 'Agrippa aber sagte zu Festus: „Dieser Mann könnte freigelassen werden, wenn er sich nicht auf Cäsar berufen hätte.“',
    },
    27: {
        1: 'Als nun entschieden worden war, dass wir nach Italia abreisen würden, übergaben sie Paulus und einige weitere Gefangene einem Zenturio namens Julius, aus der Kohorte Seiner Majestät.',
        2: 'Wir bestiegen aber ein Schiff aus Adramyttion, das zu den Orten entlang [der Küste] Asias segeln sollte, und brachen auf, wobei Aristarchus, ein Makedonier aus Thessalonich, mit uns [unterwegs] war.',
        3: 'Und am anderen [Tag] legten wir in Sidon an, und Julius behandelte Paulus freundlich und gestatte es ihm, zu den Freunden zu gehen, um [ihre] Fürsorge zu erfahren.',
        4: 'Und von dort brachen wir auf und segelten unterhalb von Zypern [entlang], weil die Winde widrig waren.',
        5: 'Dann segelten wir über die offene See entlang Kilikias und Pamphylias und legten in Myra in Lyzien an.',
        6: 'Und als der Zenturio dort ein Schiff aus Alexandrien fand, das nach Italia segelte, verlud er uns darauf.',
        7: 'Nachdem wir aber an etlichen Tagen [nur] langsam segelten und mit Mühe gen Knidos gekommen waren, weil uns der Wind nicht weiterkommen ließ, segelten wir unterhalb von Kreta gen Salmone.',
        8: 'Und während wir sie mit Mühe umfuhren, kamen wir an einen Ort, der „Kalouslimenas“genannt wird, dem die Stadt Lasäa nahe war.',
        9: 'Weil nun etliche Zeit verstrichen und die Überfahrt bereits unsicher geworden war, da auch das Fasten bereits vorüber war, mahnte Paulus [zur Vorsicht]',
        10: 'und sagte zu ihnen: „Männer, ich sehe, dass die Fahrt im Begriff steht, mit Schaden und großem Verlust zu enden, nicht nur der Ladung und des Schiffs, sondern auch unserer Leben!“',
        11: 'Der Zenturio aber vertraute dem Kapitän und dem Schiffsbesitzer mehr als dem von Paulus Gesagten.',
        12: 'Auch weil der Hafen zur Überwinterung ungeeignet war, stimmten die meisten für den Plan, von dort aufzubrechen, falls sie irgendwie nach Phönix (einem Hafen Kretas, der nach Südwesten und nach Nordwesten blickt) gelangen könnten, um [dort] zu überwintern.',
        13: 'Als nun ein Südwind wehte, meinten sie, das Vorhaben im Griff zu haben, lichteten [den Anker] und umfuhren Kreta unweit [der Küste].',
        14: 'Aber nicht lange danach rauschte ein stürmischer Wind, der sogenannte „Eurakylon“, von ihr herab.',
        15: 'Als nun das Schiff mitgerissen wurde und dem Wind nicht trotzen konnte, gaben wir auf und ließen uns treiben.',
        16: 'Erst als wir unterhalb einer gewissen Insel, die Kauda genannt wird, entlangfuhren, konnten wir mit Mühe das Beiboot ‹unter Kontrolle bringen›.',
        17: 'Das zogen sie herauf und wandten Hilfsmaßnahmen an, indem sie das Schiff umgurteten, und da sie fürchteten, dass sie in die Syrte abgetrieben würden, senkten sie das Gerät und ließen sich auf diese Weise treiben.',
        18: 'Da wir vom Unwetter aber heftig geplagt wurden, begannen sie am nächsten [Tag], ‹Ladung über Bord zu werfen›,',
        19: 'und am dritten [Tag] warfen sie eigenhändig die Schiffsausrüstung ab.',
        20: 'Und als über mehrere Tage weder Sonne noch Sterne erschienen und sich ein nicht [gerade] kleines Unwetter abzeichnete, wurde uns schließlich alle Hoffnung genommen, gerettet zu werden.',
        21: 'Als nun eine große Appetitlosigkeit vorherrschte, da stand Paulus in ihrer Mitte auf und sagte: „Oh Männer, es wäre freilich angebracht gewesen, mir zu vertrauen, um nicht von Kreta aufzubrechen und diesen Schaden und Verlust zu ernten.',
        22: 'Und doch ermahne ich euch jetzt, guten Mutes zu sein! Kein einziger Untergang eines Menschenleben von euch wird nämlich passieren, lediglich des Schiffs.',
        23: 'Denn in dieser Nacht stand ein Engel des Gottes bei mir, dem ich gehöre [und] dem ich auch diene,',
        24: 'und sagte: ‚Fürchte dich nicht, Paulus! Du musst Cäsar gegenübertreten, und siehe!, Gott hat dir alle geschenkt, die mit dir segeln.‘',
        25: 'Darum seid guten Mutes, Männer! Denn ich vertraue Gott, dass es so sein wird – ‹genau wie› mir gesagt worden ist.',
        26: 'Auf irgendeiner Insel aber müssen wir auf Grund laufen.“',
        27: 'Als es nun die vierzehnte Nacht war – während wir im Adriatischen Meer trieben –, da vermuteten gegen Mitternacht die Seeleute, dass sich ihnen irgendein Festland näherte.',
        28: 'Und als sie [die Tiefe] ausloteten, stellten sie zwanzig Faden fest; nachdem sie aber ein kurzes [Stück] weitergekommen waren und wieder [die Tiefe] ausloteten, stellten sie fünfzehn Faden fest.',
        29: 'Und da sie befürchteten, dass wir irgendwo gegen schroffe Stellen abtreiben könnten, warfen sie vier Anker vom Heck und beteten, dass es Tag werde.',
        30: 'Während nun die Matrosen von dem Schiff zu fliehen versuchten und das Beiboot unter dem Vorwand ins Meer senkten, als hätten sie vor, einen Anker vom Bug auszuwerfen,',
        31: 'da sagte Paulus zu dem Zenturio und den Soldaten: „Wenn diese [Männer] nicht im Schiff bleiben, dann könnt ihr nicht gerettet werden.“',
        32: 'Daraufhin kappten die Soldaten die Taue des Beibootes und ließen es wegtreiben.',
        33: 'Als es nun Tag werden sollte, forderte Paulus alle auf, Essen zu sich zu nehmen, und sagte: „Heute wartet und verharrt ihr den vierzehnten Tag ohne Essen, weil ihr nichts zu euch genommen habt.',
        34: 'Darum fordere ich auf euch, Essen zu euch zu nehmen! Denn das gehört zu eurer Rettung, denn keinem von euch wird ein Haar vom Kopf verloren gehen.“',
        35: 'Und nachdem er diese [Dinge] gesagt und ein Brot genommen hatte, dankte er Gott vor allen, und dann brach er es und begann zu essen.',
        36: 'Als nun alle guten Mutes geworden waren, nahmen auch sie Essen zu sich.',
        37: '(Wir waren aber insgesamt 276 Personen auf dem Schiff.)',
        38: 'Und nachdem sie vom Essen gesättigt waren, machten sie das Boot leichter, indem sie das Getreide ins Meer warfen.',
        39: 'Als es nun Tag wurde, erkannten sie das Land nicht, aber sie bemerkten irgendeine Bucht, die einen Strand hatte, an den sie – wenn sie könnten – das Boot landen wollten.',
        40: 'Und sie kappten die Anker und ließen sie in das Meer, gleichzeitig lockerten sie die Taue der Ruder und hissten das Vordersegel für den wehenden [Wind] und hielten Kurs auf den Strand.',
        41: 'Sie gerieten aber in eine Sandbank und setzten das Schiff auf Grund, und zwar saß der Bug fest und blieb unbeweglich, das Heck hingegen zerbrach unter der Gewalt der Wellen.',
        42: 'Seitens der Soldaten entstand nun der Plan, die Gefangenen zu töten, damit niemand wegschwimmt und entkommt.',
        43: 'Der Zenturio hingegen wollte Paulus in Sicherheit bringen und hinderte sie an dem Vorhaben, und er befahl denen, die schwimmen konnten, als Erste abzuspringen und an Land zu gehen',
        44: 'und den übrigen teils auf Brettern, teils auf irgendwelchen [Dingen] vom Schiff. Und so geschah es, dass alle sicher an Land gebracht wurden.',
    },
    28: {
        1: 'Und nachdem wir dann in Sicherheit gebracht worden waren, erfuhren wir, dass die Insel Melite genannt wird.',
        2: 'Und die Eingeborenen erwiesen uns außergewöhnliche Freundlichkeit, denn sie zündeten ein Feuer an und nahmen uns wegen des einsetzenden Regens und wegen der Kälte alle zu sich auf.',
        3: 'Als nun Paulus ein Bündel Reisig zusammengetragen und auf das Feuer gelegt hatte, da kam aufgrund der Hitze eine Schlange heraus und biss sich an seiner Hand fest.',
        4: 'Als aber die Eingeborenen das Tier von seiner Hand hängen sahen, sagten sie zueinander: „Zweifellos ist dieser Mann ein Mörder, den Dike, obwohl er aus Seenot gerettet wurde, nicht leben ließ.“',
        5: 'Er schüttelte also das Tier in das Feuer und erlitt nichts Schlimmes,',
        6: 'aber sie erwarteten, dass er anschwellen oder plötzlich tot umfallen würde. Während sie nun lange warteten und nichts Ungewöhnliches an ihm geschehen sahen, änderten sie [ihre Meinung] und sagten, dass er ein Gott sei.',
        7: 'Aber in der Umgebung jenes Ortes gehörten dem wichtigsten [Mann] der Insel Ländereien – [einem Mann] namens Publius, der uns aufnahm und drei Tage freundlich beherbergte.',
        8: 'Da geschah es, dass der Vater von Publius Fieber und Durchfall bekam und niederlag; zu dem ging Paulus hinein, und betend legte er ihm die Hände auf und heilte ihn.',
        9: 'Nachdem sich dies nun ereignet hatte, kamen auch die übrigen auf der Insel herbei, die Krankheiten hatten, und sie wurden geheilt.',
        10: 'Sie ehrten uns auch ‹ganz besonders›, und als wir aufbrachen, luden sie uns ‹alles Notwendige› auf.',
        11: 'Nach nunmehr drei Monaten brachen wir in einem alexandrischen Schiff auf, das auf der Insel überwintert hatte, mit dem Zeichen der Dioskuren.',
        12: 'Und nachdem wir in Syrakus angelegt hatten, blieben wir drei Tage.',
        13: 'Von dort nahmen wir einen Umweg und gelangten nach Rhegion, und als einen Tag später ein Südwind aufkam, kamen wir am zweiten nach Puteoli,',
        14: 'wo wir [einige] Brüder fanden und gebeten wurden, sieben Tage bei ihnen zu bleiben; und so kamen wir nach Rom.',
        15: 'Und von dort kamen die Brüder, als sie ‹von unserer Lage› hörten, zur Begegnung mit uns bis zum Forum Appius und den Tres Tabernae. Als Paulus sie sah, dankte er Gott und schöpfte Mut.',
        16: 'Als wir nun nach Rom kamen, wurde es Paulus gestattet, ganz für sich zu bleiben, zusammen mit dem Soldaten, der ihn bewachte.',
        17: 'Es geschah aber nach drei Tagen, dass er diejenigen zusammenrief, die von den Judäern wichtig waren; als sie sich nun versammelten hatten, sagte er zu ihnen: „Obwohl ich, Männer, Brüder, nichts gegen das Volk oder die Bräuche unserer Väter getan habe, bin ich als Gefangener aus Jerusalem in die Hände der Römer übergeben worden,',
        18: 'welche mich freilassen wollten, nachdem sie mich verhört hatten, weil nicht der geringste Anlass zur Todesstrafe in meinem Fall bestand.',
        19: 'Da aber die Judäer widersprachen, war ich gezwungen, an Cäsar zu appellieren – nicht als hätte ich meinem Volk etwas vorzuwerfen.',
        20: 'Aus diesem Grund habe ich also gebeten, euch zu sehen und anzusprechen, denn wegen der Hoffnung Israels trage ich diese Kette!“',
        21: 'Sie aber sagten zu ihm: „Wir haben weder Briefe über dich aus Judäa empfangen noch kam irgendeiner der Brüder und hat etwas Böses über dich berichtet oder gesagt.',
        22: 'Wir möchten aber von dir hören, was du denkst, denn über diese Sekte ist uns bekannt, dass ihr überall widersprochen wird.“',
        23: 'Nachdem sie nun einen Tag für ihn festgelegt hatten, kamen mehrere zu ihm in die Herberge, denen er das Reich Gottes auslegte und bezeugte und sie von früh morgens bis spät abends in Bezug auf Jesus überzeugen wollte, sowohl vom Gesetz des Mose her als auch von den Propheten her.',
        24: 'Und einige wurden durch das Gesagte überzeugt, andere glaubten nicht;',
        25: 'aber da sie untereinander uneins waren, trennten sie sich, nachdem Paulus eine einzige Aussage machte: „Treffend hat der heilige Geist durch Jesaja den Propheten zu euren Vorfahren geredet,',
        26: 'als er sagte: ‚Geh zu diesem Volk und sprich: Ihr werdet genau hinhören und nicht verstehen, und ihr werdet genau hinsehen und nicht wahrnehmen!',
        27: 'Das Herz dieses Volkes ist nämlich abgestumpft, und mit den Ohren haben sie schwer gehört, und ihre Augen haben sie geschlossen; sonst sehen sie mit den Augen und hören sie mit den Ohren und verstehen sie mit dem Herz und kehren sie um, und dann würde ich sie heilen.‘',
        28: 'Es soll euch also bekannt sein, dass dieses Heil Gottes zu den [heidnischen] Völkern gesandt wurde; sie werden auch hören.“',
        30: 'Er blieb aber insgesamt zwei Jahre in seinem eigenen Mietshaus und empfing alle, die zu ihm kamen,',
        31: 'predigte das Reich Gottes und lehrte, was über den Herrn Jesus Christus [zu sagen ist], ungehindert [und] mit aller Freimütigkeit.',
    },
}
